	@Override
	protected void startUp()
	{
		syncRewardPriority();
		overlayManager.add(overlay);
		overlayManager.add(potionOverlay);
		overlayManager.add(goalInfoBoxOverlay);
		overlayManager.add(ordersPanelOverlay);
		previouslyAboveRewardThreshold = false;
