package com.oveduumnakal.anothermixology;

import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import net.runelite.api.gameval.ItemID;
import net.runelite.client.util.Text;

/**
 * Digweed handling that needs no client state: the item, reading which potion a digweed improved from the chat, and
 * which order that potion belongs to. A digweed doubles one potion's resin; the improved potion keeps its item id, so
 * the chat message is the only sign of which one it was.
 */
final class Digweed
{
	static final int ITEM_ID = ItemID.MM_LAB_SPECIAL_HERB;

	/**
	 * Matches "You mix the digweed into the Mixalot, drastically improving its quality!"; the OSRS Wiki quotes the same
	 * ending for the reverse use of a potion on the digweed. The game wraps the potion name in a colour code such as
	 * {@code @mes_hl_pur@}, which {@link #COLOUR_CODE} strips.
	 */
	private static final Pattern IMPROVED = Pattern.compile("into the (.+?), drastically improving its quality",
			Pattern.CASE_INSENSITIVE);

	private static final Pattern COLOUR_CODE = Pattern.compile("@[a-z_]+@");

	private Digweed()
	{
	}

	/**
	 * Returns the potion a digweed just improved, read from a chat message, or null if the message is not about
	 * digweed.
	 */
	static PotionType improvedPotion(String message)
	{
		Matcher matcher = IMPROVED.matcher(COLOUR_CODE.matcher(Text.removeTags(message)).replaceAll(""));
		if (!matcher.find())
			return null;

		String name = matcher.group(1).trim();
		for (PotionType type : PotionType.TYPES)
		{
			if (String.join("", type.nameParts()).equalsIgnoreCase(name))
				return type;
		}

		return null;
	}

	/**
	 * Picks the order an improved potion belongs to among the orders of its type not yet improved: the digweed target
	 * slot first, then a recommended order, then any, each in display order.
	 *
	 * @param targetSlot the slot the digweed was highlighted for, or -1
	 * @return the order, or null if no order of that type is left to improve
	 */
	static PotionOrder orderImproved(List<PotionOrder> orders, PotionType type, int targetSlot,
			Set<Integer> recommendedSlots)
	{
		PotionOrder planned = null;
		PotionOrder any = null;
		for (PotionOrder order : orders)
		{
			if (order.potionType() != type || order.improved())
				continue;

			if (order.idx() == targetSlot)
				return order;

			if (planned == null && MixGuidance.planned(order, recommendedSlots))
				planned = order;

			if (any == null)
				any = order;
		}

		return planned != null ? planned : any;
	}
}

package com.oveduumnakal.anothermixology;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.geom.Area;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/**
 * Draws the digweed mark: a five-pointed leaf in the digweed colour with a dark edge, which reads better at a small
 * size than the digweed item image.
 */
final class DigweedIcon
{
	/** Each lobe's angle from straight up, in degrees, and its length as a share of the icon size. */
	private static final double[][] LOBES = {{0, 0.60}, {-50, 0.50}, {50, 0.50}, {-100, 0.34}, {100, 0.34}};

	private DigweedIcon()
	{
	}

	/** Returns a square leaf icon of the given size in the given colour. */
	static BufferedImage create(int size, Color color)
	{
		var image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		var graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		double baseX = size / 2.0;
		double baseY = size * 0.66;
		var leaf = new Area();
		for (double[] lobe : LOBES)
		{
			double length = size * lobe[1];
			double half = length * 0.36;
			var shape = new Path2D.Double();
			shape.moveTo(baseX, baseY);
			shape.curveTo(baseX - half * 1.4, baseY - length * 0.35, baseX - half * 0.6, baseY - length * 0.8, baseX,
					baseY - length);
			shape.curveTo(baseX + half * 0.6, baseY - length * 0.8, baseX + half * 1.4, baseY - length * 0.35, baseX,
					baseY);
			shape.closePath();
			var turn = AffineTransform.getRotateInstance(Math.toRadians(lobe[0]), baseX, baseY);
			leaf.add(new Area(turn.createTransformedShape(shape)));
		}

		var edge = new Color(color.getRed() / 3, color.getGreen() / 3, color.getBlue() / 3);
		float stroke = Math.max(1f, size / 24f);
		graphics.setStroke(new BasicStroke(stroke, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(edge);
		graphics.draw(new Line2D.Double(baseX, baseY, baseX, size - stroke));
		graphics.setColor(color);
		graphics.fill(leaf);
		graphics.setColor(edge);
		graphics.draw(leaf);
		graphics.dispose();
		return image;
	}
}

package com.oveduumnakal.anothermixology;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Recommends the delivery that gives the most useful resin per potion over the long run.
 *
 * <p>Every non-empty subset of the three orders is a possible delivery. Its useful resin is the resin it gives,
 * including the +20% (two orders) or +40% (three orders) batch bonus, with each colour capped at what is still needed
 * for the target. Each colour's resin is then weighted by the cube of its deficit relative to the largest one: the
 * colour furthest behind takes longest to finish, so its resin is worth the most, and the steep weighting keeps the
 * other colours from finishing early and wasting resin. The exponent 3 was the fastest of 0.5 to 10 in simulation.
 * Delivering refreshes all three orders, so each potion brewed now has an opportunity cost: the
 * useful resin per potion the player can expect from future order sets. That rate is found by Dinkelbach iteration
 * over every possible order set, weighted by the in-game order chances, and the delivery that beats it by the most
 * wins.
 *
 * <p>Time is counted in average potions. Each delivery also costs {@link #DEPOSIT_COST} potions of time for the walk
 * to the conveyor belt and the start of the next set. Every choice includes exactly one delivery, so this cost does
 * not change the comparison within one order set; it lowers the long-run rate, which makes extra potions in the
 * current set worth brewing more often. When the orders' modifiers are known, each potion in the current set costs its
 * station's time (see {@link #potionCost(PotionModifier)}); future sets use the average.
 *
 * <p>A digweed doubles one potion's resin, and the batch bonus applies to the doubled amount. Potions it already
 * improved count double, and each digweed the player holds goes on the slot of a delivery where it adds the most
 * useful resin, so an order worth brewing only with a digweed gets recommended. Future sets assume no digweed.
 */
public class ExpectedValuePolicy implements RecommendationPolicy
{
	private static final int[][] SUBSETS = {{0}, {1}, {2}, {0, 1}, {0, 2}, {1, 2}, {0, 1, 2}};
	private static final int MAX_ITERATIONS = 50;
	private static final double EPSILON = 1e-6;

	/**
	 * The time one delivery costs, in average potions. A fit over 40 order sets of 2026-10-29 lab play gave 11.3
	 * seconds per delivery, and 15.5 (Alembic), 18.7 (Retort) and 15.4 (Agitator) seconds per potion.
	 */
	static final double DEPOSIT_COST = 0.7;

	/** The power each colour's relative deficit is raised to for its weight. */
	static final double WEIGHT_EXPONENT = 3;
	private static final double[] AVERAGE_COST = {1, 1, 1};
	private static final List<Draw> DRAWS = draws();

	@Override
	public Set<Integer> decide(PotionType[] orders, int[] resin, int[] target)
	{
		return decide(OrderSet.of(orders), resin, target);
	}

	@Override
	public Set<Integer> decide(OrderSet orderSet, int[] resin, int[] target)
	{
		int[] deficit = MetaPolicy.deficit(resin, target);
		if (deficit[0] == 0 && deficit[1] == 0 && deficit[2] == 0)
			return MetaPolicy.all3();

		double[] cost = new double[orderSet.orders().length];
		for (int slot = 0; slot < cost.length; slot++)
			cost[slot] = potionCost(orderSet.modifiers()[slot]);

		double[] weight = weights(deficit);
		int[] best = bestSubset(orderSet, cost, deficit, weight, longRunRate(deficit, weight));
		Set<Integer> slots = new HashSet<>();
		if (best != null)
		{
			for (int slot : best)
				slots.add(slot);
		}

		return slots;
	}

	/**
	 * Returns the weighted useful resin per potion of time that the best play earns on average from a fresh order
	 * set, holding the deficit fixed. Each delivery adds {@link #DEPOSIT_COST} to the time.
	 */
	static double longRunRate(int[] deficit, double[] weight)
	{
		double rate = 0;
		for (int iteration = 0; iteration < MAX_ITERATIONS; iteration++)
		{
			double resin = 0;
			double potions = 0;
			for (Draw draw : DRAWS)
			{
				int[] best = bestSubset(OrderSet.of(draw.orders), AVERAGE_COST, deficit, weight, rate);
				resin += draw.chance * gain(draw.orders, best, deficit, weight);
				potions += draw.chance * (best.length + DEPOSIT_COST);
			}

			double next = resin / potions;
			if (Math.abs(next - rate) < EPSILON)
				return next;

			rate = next;
		}

		return rate;
	}

	/**
	 * Returns the time one potion takes at its modifier's station, in average potions; 1 when the modifier is not
	 * known.
	 */
	static double potionCost(PotionModifier modifier)
	{
		if (modifier == null)
			return 1;

		switch (modifier)
		{
			case CRYSTALISED:
				return 0.94;
			case CONCENTRATED:
				return 1.13;
			case HOMOGENOUS:
				return 0.93;
			default:
				return 1;
		}
	}

	/**
	 * Returns the delivery with the highest weighted useful resin minus the opportunity cost of its potions' time; a
	 * tie goes to the delivery with more useful resin. Returns null when no order is known.
	 *
	 * @param cost each slot's potion time, in average potions
	 */
	static int[] bestSubset(OrderSet orderSet, double[] cost, int[] deficit, double[] weight, double rate)
	{
		int[] best = null;
		double bestScore = Double.NEGATIVE_INFINITY;
		double bestGain = -1;
		for (int[] subset : SUBSETS)
		{
			if (!known(orderSet.orders(), subset))
				continue;

			double gain = bestGain(orderSet, subset, deficit, weight);
			double time = 0;
			for (int slot : subset)
				time += cost[slot];

			double score = gain - rate * time;
			if (score > bestScore + EPSILON || (score > bestScore - EPSILON && gain > bestGain))
			{
				best = subset;
				bestScore = score;
				bestGain = gain;
			}
		}

		return best;
	}

	/**
	 * Returns the weighted useful resin of delivering the given slots together: the base resin times 1, 1.2 or 1.4 for
	 * one, two or three orders, each colour capped at its deficit and multiplied by its weight.
	 */
	static double gain(PotionType[] orders, int[] subset, int[] deficit, double[] weight)
	{
		return gain(orders, subset, new boolean[orders.length], deficit, weight);
	}

	/**
	 * Returns the weighted useful resin of delivering the given slots together, as {@link #gain(PotionType[], int[],
	 * int[], double[])} does, with each doubled slot's resin counted twice.
	 */
	static double gain(PotionType[] orders, int[] subset, boolean[] doubled, int[] deficit, double[] weight)
	{
		int bonusFifths = 4 + subset.length;
		double total = 0;
		for (int colour = 0; colour < 3; colour++)
		{
			int resin = 0;
			for (int slot : subset)
				resin += orders[slot].resinYield(colour) * (doubled[slot] ? 2 : 1);

			total += weight[colour] * Math.min(deficit[colour], resin * bonusFifths / 5);
		}

		return total;
	}

	/**
	 * Returns the weighted useful resin of delivering the given slots, with the improved potions doubled and each held
	 * digweed placed on the slot where it adds the most.
	 */
	static double bestGain(OrderSet orderSet, int[] subset, int[] deficit, double[] weight)
	{
		PotionType[] orders = orderSet.orders();
		boolean[] improved = orderSet.improved();
		if (orderSet.digweed() == 0)
			return gain(orders, subset, improved, deficit, weight);

		double best = Double.NEGATIVE_INFINITY;
		for (int mask = 0; mask < 1 << subset.length; mask++)
		{
			boolean[] doubled = improved.clone();
			int used = 0;
			boolean valid = true;
			for (int i = 0; i < subset.length; i++)
			{
				if ((mask & 1 << i) == 0)
					continue;

				if (improved[subset[i]])
					valid = false;

				doubled[subset[i]] = true;
				used++;
			}

			if (valid && used <= orderSet.digweed())
				best = Math.max(best, gain(orders, subset, doubled, deficit, weight));
		}

		return best;
	}

	/**
	 * Returns the slot a held digweed should go on: among the recommended slots not yet improved, the one whose
	 * doubling adds the most weighted useful resin to the recommended delivery; a tie goes to the lower slot. Returns
	 * -1 when there is no such slot.
	 *
	 * @param recommended the slots that will be delivered together
	 */
	static int digweedSlot(OrderSet orderSet, Set<Integer> recommended, int[] deficit)
	{
		PotionType[] orders = orderSet.orders();
		int[] subset = recommended.stream()
				.filter(slot -> orders[slot] != null)
				.mapToInt(Integer::intValue)
				.sorted()
				.toArray();
		double[] weight = weights(deficit);
		int bestSlot = -1;
		double bestGain = Double.NEGATIVE_INFINITY;
		for (int slot : subset)
		{
			if (orderSet.improved()[slot])
				continue;

			boolean[] doubled = orderSet.improved().clone();
			doubled[slot] = true;
			double gain = gain(orders, subset, doubled, deficit, weight);
			if (gain > bestGain + EPSILON)
			{
				bestSlot = slot;
				bestGain = gain;
			}
		}

		return bestSlot;
	}

	/**
	 * Weights each colour by its deficit relative to the largest one, raised to {@link #WEIGHT_EXPONENT}, from 0 (not
	 * needed) to 1.
	 */
	static double[] weights(int[] deficit)
	{
		int max = Math.max(deficit[0], Math.max(deficit[1], deficit[2]));
		double[] weight = new double[3];
		for (int colour = 0; colour < 3; colour++)
			weight[colour] = max == 0 ? 0 : Math.pow(deficit[colour] / (double) max, WEIGHT_EXPONENT);

		return weight;
	}

	private static boolean known(PotionType[] orders, int[] subset)
	{
		for (int slot : subset)
		{
			if (orders[slot] == null)
				return false;
		}

		return true;
	}

	/** Returns every unordered set of three orders once, with its chance of being drawn. */
	static List<Draw> orderDraws()
	{
		return DRAWS;
	}

	/** Lists every unordered set of three orders once, with its chance of being drawn. */
	private static List<Draw> draws()
	{
		PotionType[] types = PotionType.TYPES;
		double totalWeight = 0;
		for (PotionType type : types)
			totalWeight += type.orderWeight();

		List<Draw> draws = new ArrayList<>();
		for (int a = 0; a < types.length; a++)
		{
			for (int b = a; b < types.length; b++)
			{
				for (int c = b; c < types.length; c++)
				{
					int orderings = a == b && b == c ? 1 : (a == b || b == c ? 3 : 6);
					double chance = orderings * types[a].orderWeight() * types[b].orderWeight() * types[c].orderWeight()
							/ (totalWeight * totalWeight * totalWeight);
					draws.add(new Draw(new PotionType[]{types[a], types[b], types[c]}, chance));
				}
			}
		}

		return draws;
	}

	/** One possible set of three orders and its chance of being drawn. */
	static final class Draw
	{
		final PotionType[] orders;
		final double chance;

		Draw(PotionType[] orders, double chance)
		{
			this.orders = orders;
			this.chance = chance;
		}
	}
}

package com.oveduumnakal.anothermixology;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

import net.runelite.api.Client;

/**
 * The reward goal behind the overlay: the rewards ticked in Reward Tracking, their summed resin cost and how close
 * the player's current resin is to it.
 */
public class Goal
{
	private RewardItem rewardItem;
	private String displayName;
	private boolean multiMode = false;
	private double overallProgress = 0.0;

	/** Rebuilt for every component each time the goal is recalculated, so the values are never stale. */
	private final Map<PotionComponent, ComponentData> componentDataMap = new EnumMap<>(PotionComponent.class);

	public Goal(RewardItem rewardItem)
	{
		this.rewardItem = rewardItem;
		this.displayName = rewardItem.itemName();
	}

	public RewardItem getRewardItem()
	{
		return rewardItem;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public boolean isMultiMode()
	{
		return multiMode;
	}

	public double getOverallProgress()
	{
		return overallProgress;
	}

	public ComponentData getComponentData(PotionComponent component)
	{
		return componentDataMap.get(component);
	}

	/**
	 * Rebuilds the goal from the Reward Tracking settings and the player's current resin.
	 *
	 * <p>The cost of every ticked reward is summed per resin colour and the first one supplies the icon. The overall
	 * progress is the average of the colours' progress.
	 *
	 * @param config the plugin config holding the ticked rewards and their quantities
	 * @param client the client the current resin amounts are read from
	 */
	public void recalculate(AnotherMixologyConfig config, Client client)
	{
		List<Selection> selected = collectSelections(config);

		if (!selected.isEmpty())
		{
			multiMode = true;
			rewardItem = selected.get(0).item;
			displayName = selected.size() == 1
					? formatSingleDisplayName(selected.get(0))
					: "Selected rewards (" + selected.size() + ")";

			for (var component : PotionComponent.ENTRIES)
			{
				int currentAmount = client.getVarpValue(component.resinVarpId());
				int summedCost = 0;
				for (Selection sel : selected)
					summedCost += sel.item.componentCost(component) * sel.quantity;

				componentDataMap.put(component, new ComponentData(currentAmount, summedCost));
			}
		}
		else
		{
			multiMode = false;
			rewardItem = RewardItem.NONE;
			displayName = "";

			for (var component : PotionComponent.ENTRIES)
			{
				int currentAmount = client.getVarpValue(component.resinVarpId());
				componentDataMap.put(component, new ComponentData(currentAmount, 0));
			}
		}

		overallProgress = componentDataMap.values().stream()
				.mapToDouble(data -> data.percentageToGoal)
				.average()
				.orElse(0.0);
	}

	private static String formatSingleDisplayName(Selection sel)
	{
		if (sel.quantity > 1)
			return sel.item.itemName() + " x" + sel.quantity;

		return sel.item.itemName();
	}

	static List<Selection> collectSelections(AnotherMixologyConfig config)
	{
		List<Selection> list = new ArrayList<>();
		if (config.trackPrescriptionGoggles())
			list.add(new Selection(RewardItem.PRESCRIPTION_GOGGLES, 1));

		if (config.trackAlchemistLabcoat())
			list.add(new Selection(RewardItem.ALCHEMIST_LABCOAT, 1));

		if (config.trackAlchemistPants())
			list.add(new Selection(RewardItem.ALCHEMIST_PANTS, 1));

		if (config.trackAlchemistGloves())
			list.add(new Selection(RewardItem.ALCHEMIST_GLOVES, 1));

		if (config.trackReagentPouch())
			list.add(new Selection(RewardItem.REAGENT_POUCH, 1));

		if (config.trackPotionStorage())
			list.add(new Selection(RewardItem.POTION_STORAGE, 1));

		if (config.chuggingBarrelQuantity() > 0)
			list.add(new Selection(RewardItem.CHUGGING_BARREL, config.chuggingBarrelQuantity()));

		if (config.trackAlchemistsAmulet())
			list.add(new Selection(RewardItem.ALCHEMISTS_AMULET, 1));

		if (config.apprenticePackQuantity() > 0)
			list.add(new Selection(RewardItem.APPRENTICE_POTION_PACK, config.apprenticePackQuantity()));

		if (config.adeptPackQuantity() > 0)
			list.add(new Selection(RewardItem.ADEPT_POTION_PACK, config.adeptPackQuantity()));

		if (config.expertPackQuantity() > 0)
			list.add(new Selection(RewardItem.EXPERT_POTION_PACK, config.expertPackQuantity()));

		if (config.aldariumQuantity() > 0)
			list.add(new Selection(RewardItem.ALDARIUM, config.aldariumQuantity()));

		return RewardPriority.sort(list, RewardPriority.parse(config.rewardPriority()));
	}

	/** A ticked reward and how many of it are wanted. */
	static final class Selection
	{
		final RewardItem item;
		final int quantity;

		Selection(RewardItem item, int quantity)
		{
			this.item = item;
			this.quantity = quantity;
		}
	}

	/** One resin colour's stock against the summed goal, with the progress derived from them. */
	public static class ComponentData
	{
		final int currentAmount;
		final int goalAmount;
		final double percentageToGoal;

		ComponentData(int currentAmount, int goalAmount)
		{
			this.currentAmount = currentAmount;
			this.goalAmount = goalAmount;
			this.percentageToGoal = goalAmount == 0 ? 1.0 : Math.min((double) currentAmount / goalAmount, 1.0);
		}
	}
}

package com.oveduumnakal.anothermixology;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;

import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.QuantityFormatter;

/**
 * The rewards panel: a row per tracked reward with its icon, estimated time to completion and progress, a row for all
 * of them together, then a progress bar per resin colour. Faint lines separate the sections. It shows only while the
 * potion orders do; the Show rewards panel setting hides it, and Show reward times drops the time column.
 */
class GoalInfoBoxOverlay extends OverlayPanel
{
	private static final int BORDER_SIZE = 3;
	private static final int VERTICAL_GAP = 2;
	private static final int ICON_AND_GOAL_GAP = 5;
	private static final int MIN_WIDTH = 250;
	private static final int COMPONENT_SPRITE_SIZE = 16;
	private static final Color PROGRESS_BAR_BACKGROUND_COLOR = new Color(61, 56, 49);
	private static final Color READY_COLOR = Color.GREEN;
	private static final Color PENDING_COLOR = Color.GRAY;

	private final AnotherMixologyPlugin plugin;
	private final AnotherMixologyConfig config;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;

	private final BufferedImage[] componentSprites = new BufferedImage[PotionComponent.ENTRIES.length];

	@Inject
	GoalInfoBoxOverlay(
			AnotherMixologyPlugin plugin,
			AnotherMixologyConfig config,
			ItemManager itemManager,
			SpriteManager spriteManager
	)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;

		setPosition(OverlayPosition.TOP_RIGHT);
		setPriority(PRIORITY_MED);
		panelComponent.setPreferredSize(new Dimension(MIN_WIDTH, 0));
		panelComponent.setBorder(new Rectangle(BORDER_SIZE, BORDER_SIZE, BORDER_SIZE, BORDER_SIZE));
		panelComponent.setGap(new Point(0, VERTICAL_GAP));
	}

	/**
	 * Draws the reward rows, the all-rewards row when more than one reward is tracked, and a progress bar per resin
	 * colour.
	 */
	@Override
	public Dimension render(Graphics2D graphics)
	{
		var goal = plugin.getGoal();
		var estimates = plugin.rewardEstimates();
		if (!config.showRewardsPanel() || !goal.isMultiMode() || !plugin.isOrdersPanelVisible() || estimates == null)
			return null;

		graphics.setFont(FontManager.getRunescapeSmallFont());
		var metrics = graphics.getFontMetrics();
		int labelColumn = 0;
		for (var row : estimates.rows)
			labelColumn = Math.max(labelColumn, metrics.stringWidth(row.label));

		boolean showTimes = config.showRewardTimes();
		var numberMetrics = graphics.getFontMetrics(NumberFont.matching(graphics, graphics.getFont()));
		int width = panelWidth(labelColumn, numberMetrics.stringWidth(RewardRowComponent.WIDEST_TIME),
				numberMetrics.stringWidth(RewardRowComponent.WIDEST_PERCENT), showTimes);
		panelComponent.setPreferredSize(new Dimension(width, 0));

		long now = plugin.playedMillis();
		int rewards = estimates.rows.size() - 1;
		for (int i = 0; i < rewards; i++)
			panelComponent.getChildren().add(rowComponent(estimates, i, labelColumn, now, showTimes));

		if (rewards > 1)
		{
			panelComponent.getChildren().add(new SeparatorComponent());
			panelComponent.getChildren().add(rowComponent(estimates, rewards, labelColumn, now, showTimes));
		}

		panelComponent.getChildren().add(new SeparatorComponent());
		for (var component : PotionComponent.ENTRIES)
			createProgressBar(goal, component);

		return super.render(graphics);
	}

	/**
	 * Returns the panel width: the icon, name, time and percent columns with a gap between each, plus the border, and
	 * never less than {@code MIN_WIDTH}. Without times the time column and its gap are left out.
	 */
	static int panelWidth(int labelColumn, int timeWidth, int percentWidth, boolean showTimes)
	{
		int width = RewardRowComponent.ICON_COLUMN + labelColumn + RewardRowComponent.GAP + percentWidth
				+ BORDER_SIZE * 2;
		if (showTimes)
			width += timeWidth + RewardRowComponent.GAP;

		return Math.max(MIN_WIDTH, width);
	}

	/**
	 * Builds a reward row, its time counted down to {@code now}, in {@link PlayClock} milliseconds played. Without
	 * times the row has no time column.
	 */
	private RewardRowComponent rowComponent(RewardEstimates estimates, int index, int labelColumn, long now,
			boolean showTimes)
	{
		var row = estimates.rows.get(index);
		double seconds = estimates.seconds[index];
		String time;
		Color timeColor;
		if (!showTimes)
		{
			time = null;
			timeColor = null;
		}
		else if (row.ready())
		{
			time = "Ready";
			timeColor = READY_COLOR;
		}
		else if (Double.isNaN(seconds))
		{
			time = "...";
			timeColor = PENDING_COLOR;
		}
		else if (Double.isInfinite(seconds))
		{
			time = "--";
			timeColor = PENDING_COLOR;
		}
		else
		{
			time = RewardRows.formatTime(estimates.secondsLeft(index, now));
			timeColor = Color.WHITE;
		}

		var icon = row.item == null ? null : itemManager.getImage(row.item.itemId());
		return new RewardRowComponent(icon, row.label, time, timeColor, percent(row.progress),
				row.ready() ? READY_COLOR : Color.WHITE, labelColumn);
	}

	/** Formats a 0 to 1 progress as a whole percent, rounded down so 100% means done. */
	static String percent(double progress)
	{
		return (int) Math.floor(progress * 100) + "%";
	}

	private void createProgressBar(Goal goal, PotionComponent component)
	{
		var data = goal.getComponentData(component);
		var componentSprite = getComponentSprite(component);

		if (componentSprite == null)
			return;

		var imageComponent = new ImageComponent(componentSprite);
		var progressBarComponent = new OutlinedProgressBarComponent();

		progressBarComponent.setForegroundColor(plugin.effectiveComponentColor(component));
		progressBarComponent.setBackgroundColor(PROGRESS_BAR_BACKGROUND_COLOR);
		progressBarComponent.setValue(data.percentageToGoal * 100);
		progressBarComponent.setLeftLabel(QuantityFormatter.quantityToStackSize(data.currentAmount));
		progressBarComponent.setRightLabel(QuantityFormatter.quantityToStackSize(data.goalAmount));
		progressBarComponent.setCenterLabel(centerLabel(config.showProgress(), data));

		var progressBarSplit = SplitComponent.builder()
				.first(imageComponent)
				.second(progressBarComponent)
				.orientation(ComponentOrientation.HORIZONTAL)
				.gap(new Point(ICON_AND_GOAL_GAP, 0))
				.build();

		panelComponent.getChildren().add(progressBarSplit);
	}

	/** Returns the middle label of a resin bar: its percent, the resin still needed, or nothing. */
	static String centerLabel(ProgressLabel label, Goal.ComponentData data)
	{
		switch (label)
		{
			case PERCENT:
				return percent(data.percentageToGoal);
			case NUMBER:
				int remaining = Math.max(data.goalAmount - data.currentAmount, 0);
				return remaining > 0 ? "(" + QuantityFormatter.quantityToStackSize(remaining) + ")" : "";
			default:
				return "";
		}
	}

	private BufferedImage getComponentSprite(PotionComponent component)
	{
		var sprite = componentSprites[component.ordinal()];

		if (sprite == null)
			sprite = componentSprites[component.ordinal()] = createComponentSprite(component);

		return sprite;
	}

	/**
	 * Fetches a resin sprite, resized and centred on a square canvas.
	 *
	 * @return the sprite, or null if it is not loaded yet
	 */
	private BufferedImage createComponentSprite(PotionComponent component)
	{
		var sprite = spriteManager.getSprite(component.spriteId(), 0);
		if (sprite != null)
		{
			var resizedImage = ImageUtil.resizeImage(sprite, COMPONENT_SPRITE_SIZE, COMPONENT_SPRITE_SIZE, true);
			return ImageUtil.resizeCanvas(resizedImage, COMPONENT_SPRITE_SIZE, COMPONENT_SPRITE_SIZE);
		}

		return null;
	}
}

package com.oveduumnakal.anothermixology;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Follows which inventory slots hold potions a digweed improved. An improved potion keeps its item id, so the slot the
 * player used the digweed on is recorded and followed: a drag moves it to the slot the same item appears in, and a
 * potion that leaves for a station is picked up again when its processed form comes back. Free of client state so it
 * can be unit tested; inventories are given as item ids by slot.
 */
final class ImprovedPotionTracker
{
	/** Improved slots and the item id each holds. */
	private final Map<Integer, Integer> slots = new HashMap<>();

	/** Improved potions that left the inventory, most likely into a station, waiting to come back processed. */
	private final List<PotionType> away = new ArrayList<>();

	private int clickedSlot = -1;
	private int clickedItemId;

	/** Records the potion slot the player just used a digweed on, before the game confirms it. */
	void clicked(int slot, int itemId)
	{
		clickedSlot = slot;
		clickedItemId = itemId;
	}

	/**
	 * Records the improved potion once the game confirms it: the clicked slot when it still holds that potion, or else
	 * the first untracked slot holding a potion of the type.
	 */
	void confirmed(PotionType type, int[] items)
	{
		int slot = clickedSlot;
		clickedSlot = -1;
		if (slot >= 0 && slot < items.length && items[slot] == clickedItemId
				&& PotionType.fromItemId(items[slot]) == type)
		{
			slots.put(slot, items[slot]);
			return;
		}

		for (int i = 0; i < items.length; i++)
		{
			if (!slots.containsKey(i) && PotionType.fromItemId(items[i]) == type)
			{
				slots.put(i, items[i]);
				return;
			}
		}
	}

	/**
	 * Moves the tracked slots along with an inventory change. A tracked potion whose slot changed is looked for in a
	 * slot that newly holds the same item (a drag or swap); if there is none it is taken to be in a station, and the
	 * next slot to newly hold its processed form is tracked instead.
	 */
	void inventoryChanged(int[] before, int[] after)
	{
		List<Integer> moved = new ArrayList<>();
		slots.entrySet().removeIf(entry ->
		{
			int slot = entry.getKey();
			if (slot < after.length && after[slot] == entry.getValue())
				return false;

			moved.add(entry.getValue());
			return true;
		});

		for (int itemId : moved)
		{
			int slot = newSlotHolding(before, after, itemId);
			if (slot >= 0)
			{
				slots.put(slot, itemId);
				continue;
			}

			var type = PotionType.fromItemId(itemId);
			if (type != null)
				away.add(type);
		}

		away.removeIf(type ->
		{
			int slot = newSlotHolding(before, after, type.modifiedItemId());
			if (slot < 0)
				return false;

			slots.put(slot, type.modifiedItemId());
			return true;
		});
	}

	/** Returns the inventory slots holding improved potions. */
	Set<Integer> slots()
	{
		return Set.copyOf(slots.keySet());
	}

	/** Forgets every improved potion, for a new order set. */
	void clear()
	{
		slots.clear();
		away.clear();
		clickedSlot = -1;
	}

	private int newSlotHolding(int[] before, int[] after, int itemId)
	{
		for (int i = 0; i < after.length; i++)
		{
			boolean wasThere = i < before.length && before[i] == itemId;
			if (after[i] == itemId && !wasThere && !slots.containsKey(i))
				return i;
		}

		return -1;
	}
}

package com.oveduumnakal.anothermixology;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.annotation.Nullable;
import javax.inject.Inject;

import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Tags each potion in the inventory with its recipe, as colour blocks or, with Use Letters on, as letters. While a
 * digweed has a target, outlines the digweed and the potion it should go on, following each item's shape, and marks
 * potions a digweed improved with a small digweed in the top left corner.
 */
public class InventoryPotionOverlay extends WidgetItemOverlay
{
	private static final int SMALL_DIGWEED_SIZE = 14;

	private final AnotherMixologyPlugin plugin;
	private final AnotherMixologyConfig config;
	private final ItemManager itemManager;

	/** The digweed leaf for the corner mark, drawn again when the digweed colour changes. */
	private BufferedImage smallDigweed;
	private Color smallDigweedColor;

	@Inject
	InventoryPotionOverlay(AnotherMixologyPlugin plugin, AnotherMixologyConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnInventory();
	}

	/**
	 * Draws the recipe on a potion's inventory icon, over a black drop shadow when it is drawn as letters, and the
	 * digweed outline on the digweed and its target potion.
	 */
	@Override
	public void renderItemOverlay(Graphics2D graphics2D, int itemId, WidgetItem widgetItem)
	{
		if (!plugin.isInLab())
			return;

		var bounds = widgetItem.getCanvasBounds();
		if (itemId == Digweed.ITEM_ID)
		{
			if (plugin.digweedTargetOrder() != null)
				drawOutline(graphics2D, itemId, widgetItem);

			return;
		}

		var potion = PotionType.fromItemId(itemId);

		if (potion == null)
			return;

		int index = widgetItem.getWidget().getIndex();
		if (index == plugin.digweedTargetInventoryIndex())
			drawOutline(graphics2D, itemId, widgetItem);

		if (plugin.improvedInventoryIndexes().contains(index))
		{
			var icon = smallDigweed();
			graphics2D.drawImage(icon, bounds.x, bounds.y, null);
		}

		if (config.inventoryPotionTagType() == InventoryPotionTagType.NONE)
			return;

		var x = bounds.x + 5;
		var y = bounds.y + 30;

		if (!config.useLetters())
		{
			drawBlocks(graphics2D, potion, x, y);
			return;
		}

		drawRecipe(graphics2D, potion, x + 1, y + 1, Color.BLACK);

		if (config.inventoryPotionTagType() == InventoryPotionTagType.COLORED)
		{
			drawRecipe(graphics2D, potion, x, y, null);
			return;
		}

		drawRecipe(graphics2D, potion, x, y, Color.WHITE);
	}

	private BufferedImage smallDigweed()
	{
		var color = config.digweedHighlightColor();
		if (smallDigweed == null || !color.equals(smallDigweedColor))
		{
			smallDigweed = DigweedIcon.create(SMALL_DIGWEED_SIZE, color);
			smallDigweedColor = color;
		}

		return smallDigweed;
	}

	/** Outlines the item's shape in the digweed colour. */
	private void drawOutline(Graphics2D graphics2D, int itemId, WidgetItem widgetItem)
	{
		var bounds = widgetItem.getCanvasBounds();
		var outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), config.digweedHighlightColor());
		graphics2D.drawImage(outline, bounds.x, bounds.y, null);
	}

	private void drawRecipe(Graphics2D graphics2D, PotionType potion, int x, int y, @Nullable Color color)
	{
		graphics2D.setFont(FontManager.getRunescapeSmallFont());

		if (color != null)
		{
			graphics2D.setColor(color);
			graphics2D.drawString(potion.abbreviation(), x, y);
			return;
		}

		for (var component : potion.components())
		{
			graphics2D.setColor(plugin.effectiveComponentColor(component));
			graphics2D.drawString(String.valueOf(component.character()), x, y);
			x += graphics2D.getFontMetrics().charWidth(component.character());
		}
	}

	private void drawBlocks(Graphics2D graphics2D, PotionType potion, int x, int y)
	{
		final int side = 7;
		int top = y - side + 1;
		for (var component : potion.components())
		{
			graphics2D.setColor(plugin.effectiveComponentColor(component));
			graphics2D.fillRect(x, top, side, side);
			graphics2D.setColor(Color.BLACK);
			graphics2D.drawRect(x, top, side, side);
			x += side + 1;
		}
	}
}

package com.oveduumnakal.anothermixology;

/** How potions in the inventory are tagged with their recipe: not at all, in the resin colours, or in white. */
public enum InventoryPotionTagType
{
	NONE,
	COLORED,
	WHITE,
}

package com.oveduumnakal.anothermixology;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * Adaptive meta-policy that decides which of the 3 visible orders the
 * player should brew this turn. Implements the state machine documented in
 * {@code STRATEGY.md} §7 of PDBoegel's mastering-mixology-sim repository, with the recommended thresholds.
 *
 * <p>State is maintained across calls so the policy can detect when the
 * deficit shape transitions between (single-bottleneck / two-bottleneck /
 * balanced) regimes and switch sub-policy accordingly. Call {@link #reset()}
 * at the start of a fresh session (player enters the lab, plugin starts up).
 *
 * <p>The decision returned is the set of order indices (0..2) the player
 * should brew. The plugin draws the other orders in the skip colour.
 */
public class MetaPolicy implements RecommendationPolicy
{
	/** The deficit shape the policy is currently responding to. */
	public enum State
	{
		/** One colour is clearly furthest behind. */
		SINGLE_BN,

		/** The two furthest-behind colours are close to each other. */
		DUAL_BN,

		/** All three colours are about equally far behind. */
		BALANCED
	}

	/** Recommended thresholds from the sweep at 61k/53k/71k (mastering-mixology-sim, STRATEGY.md §7). */
	public static final double T_DUAL_IN       = 0.20;
	public static final double T_DUAL_OUT      = 0.25;
	public static final double T_BALANCED_IN   = 0.20;
	public static final double T_BALANCED_OUT  = 0.25;

	private State state = State.SINGLE_BN;

	@Override
	public void reset()
	{
		state = State.SINGLE_BN;
	}

	/**
	 * Decide which slots to brew.
	 *
	 * <p>The colours are ranked by remaining deficit, largest first. A tie goes to the lower colour index, which
	 * matches the stable sort of R's {@code order(..., decreasing=TRUE)} used by the simulator. The state then moves
	 * with hysteresis; when it leaves {@link State#BALANCED} the next state is {@link State#DUAL_BN} if the top two
	 * deficits are still close and {@link State#SINGLE_BN} otherwise.
	 *
	 * @param orders     the 3 current orders' PotionTypes (slot index = array index)
	 * @param resin      [mox, aga, lye] current resin from varps
	 * @param target     [mox, aga, lye] total target (sum of selected reward costs)
	 * @return set of order indices (0..2) the player should brew this turn
	 */
	@Override
	public Set<Integer> decide(PotionType[] orders, int[] resin, int[] target)
	{
		int[] deficit = deficit(resin, target);
		Integer[] colorIdx = rankColours(deficit);
		int dMax = deficit[colorIdx[0]];
		int dMid = deficit[colorIdx[1]];
		int dMin = deficit[colorIdx[2]];

		double gap12 = dMax == 0 ? Double.POSITIVE_INFINITY : (dMax - dMid) / (double) dMax;
		double gap13 = dMax == 0 ? Double.POSITIVE_INFINITY : (dMax - dMin) / (double) dMax;

		switch (state)
		{
			case SINGLE_BN:
				if (gap13 < T_BALANCED_IN)
					state = State.BALANCED;
				else if (gap12 < T_DUAL_IN)
					state = State.DUAL_BN;

				break;
			case DUAL_BN:
				if (gap13 < T_BALANCED_IN)
					state = State.BALANCED;
				else if (gap12 > T_DUAL_OUT)
					state = State.SINGLE_BN;

				break;
			case BALANCED:
				if (gap13 > T_BALANCED_OUT)
					state = (gap12 < T_DUAL_IN) ? State.DUAL_BN : State.SINGLE_BN;

				break;
		}

		switch (state)
		{
			case SINGLE_BN:
				return singleBn(orders, deficit, colorIdx[0]);
			case DUAL_BN:
				return dualBn(orders, deficit, colorIdx[0], colorIdx[1]);
			case BALANCED:
			default:
				return balanced(orders, deficit);
		}
	}

	/** Returns the resin still needed per colour, never below zero. */
	static int[] deficit(int[] resin, int[] target)
	{
		int[] deficit = new int[3];
		for (int c = 0; c < 3; c++)
			deficit[c] = Math.max(target[c] - resin[c], 0);

		return deficit;
	}

	/** Returns the colour indices ordered by deficit, largest first; a tie goes to the lower colour index. */
	static Integer[] rankColours(int[] deficit)
	{
		Integer[] colorIdx = {0, 1, 2};
		Arrays.sort(colorIdx, (a, b) ->
		{
			int cmp = Integer.compare(deficit[b], deficit[a]);
			return cmp != 0 ? cmp : Integer.compare(a, b);
		});
		return colorIdx;
	}

	/**
	 * single_bn: if ≥2 of the 3 orders give the top-deficit colour, brew all
	 * 3; else brew the slots that give that colour; else brew the single
	 * best-deficit slot.
	 */
	static Set<Integer> singleBn(PotionType[] orders, int[] deficit, int topColorOrd)
	{
		PotionComponent top = PotionComponent.ENTRIES[topColorOrd];
		Set<Integer> giving = slotsGiving(orders, top);
		if (giving.size() >= 2)
			return all3();

		if (!giving.isEmpty())
			return giving;

		return singleton(bestDeficitSlot(orders, deficit));
	}

	/**
	 * dual_bn: if ≥2 of the 3 orders give *both* top-2 deficit colours, brew
	 * all 3; else fall through to the single_bn rule.
	 */
	private Set<Integer> dualBn(PotionType[] orders, int[] deficit, int topOrd, int midOrd)
	{
		PotionComponent top = PotionComponent.ENTRIES[topOrd];
		PotionComponent mid = PotionComponent.ENTRIES[midOrd];
		if (countSlotsGivingBoth(orders, top, mid) >= 2)
			return all3();

		return singleBn(orders, deficit, topOrd);
	}

	/**
	 * balanced: if any order is MAL (gives all three colours) OR all 3 orders
	 * are multi-resin (not MMM/AAA/LLL), brew all 3; else brew the single
	 * best-deficit slot. The MAL trigger captures the case where a single
	 * three-colour potion is enough to justify a 3-batch even when the other
	 * slots are singletons -- the +0.4 batch bonus on MAL alone gives 28 of
	 * every colour, outweighing the overshoot from the singleton partners.
	 */
	private Set<Integer> balanced(PotionType[] orders, int[] deficit)
	{
		if (anyMal(orders) || allMultiResin(orders))
			return all3();

		return singleton(bestDeficitSlot(orders, deficit));
	}

	private static boolean givesResin(PotionType pt, PotionComponent color)
	{
		if (pt == null)
			return false;

		for (PotionComponent c : pt.components())
		{
			if (c == color)
				return true;
		}

		return false;
	}

	private static Set<Integer> slotsGiving(PotionType[] orders, PotionComponent color)
	{
		Set<Integer> result = new HashSet<>();
		for (int i = 0; i < orders.length; i++)
		{
			if (givesResin(orders[i], color))
				result.add(i);
		}

		return result;
	}

	private static int countSlotsGivingBoth(PotionType[] orders, PotionComponent a, PotionComponent b)
	{
		int count = 0;
		for (PotionType pt : orders)
		{
			if (givesResin(pt, a) && givesResin(pt, b))
				count++;
		}

		return count;
	}

	private static boolean isMultiResin(PotionType pt)
	{
		return pt != null && pt.colourCount() >= 2;
	}

	private static boolean allMultiResin(PotionType[] orders)
	{
		for (PotionType pt : orders)
		{
			if (!isMultiResin(pt))
				return false;
		}

		return true;
	}

	private static boolean isMal(PotionType pt)
	{
		return pt != null && pt.colourCount() == 3;
	}

	private static boolean anyMal(PotionType[] orders)
	{
		for (PotionType pt : orders)
		{
			if (isMal(pt))
				return true;
		}

		return false;
	}

	/**
	 * Deficit-reduction score for a slot: the sum over colours of the potion's resin yield times the colour's
	 * deficit (see {@link PotionType#resinYield(int)}).
	 */
	private static int slotScore(PotionType pt, int[] deficit)
	{
		if (pt == null)
			return Integer.MIN_VALUE;

		int score = 0;
		for (int c = 0; c < 3; c++)
			score += pt.resinYield(c) * Math.max(deficit[c], 0);

		return score;
	}

	private static int bestDeficitSlot(PotionType[] orders, int[] deficit)
	{
		int bestIdx = 0;
		int bestScore = Integer.MIN_VALUE;
		for (int i = 0; i < orders.length; i++)
		{
			int s = slotScore(orders[i], deficit);
			if (s > bestScore)
			{
				bestScore = s;
				bestIdx = i;
			}
		}

		return bestIdx;
	}

	static Set<Integer> all3()
	{
		Set<Integer> s = new HashSet<>(3);
		s.add(0);
		s.add(1);
		s.add(2);
		return s;
	}

	private static Set<Integer> singleton(int idx)
	{
		Set<Integer> s = new HashSet<>(1);
		s.add(idx);
		return s;
	}
}

package com.oveduumnakal.anothermixology;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;

/**
 * Decision logic for the mixing workflow: which order to mix next, which lever to pull,
 * and whether the vessel or conveyor belt is ready. Free of client state so it can be unit tested.
 */
final class MixGuidance
{
	/**
	 * What the levers should do right now.
	 */
	enum LeverMode
	{
		/**
		 * One specific lever is next; the others are wrong.
		 */
		PULL,
		/**
		 * No lever should be pulled: the vessel is full, or every planned order is already covered.
		 */
		BLOCKED,
		/**
		 * The plugin cannot tell what the player is making (vessel contents match no plan), so every lever is allowed.
		 */
		FREE
	}

	/**
	 * Lever decision plus the lever to pull when the mode is {@link LeverMode#PULL}.
	 */
	static final class LeverState
	{
		static final LeverState BLOCKED = new LeverState(LeverMode.BLOCKED, null);
		static final LeverState FREE = new LeverState(LeverMode.FREE, null);

		private final LeverMode mode;
		private final PotionComponent next;

		private LeverState(LeverMode mode, PotionComponent next)
		{
			this.mode = mode;
			this.next = next;
		}

		static LeverState pull(PotionComponent next)
		{
			return new LeverState(LeverMode.PULL, next);
		}

		LeverMode mode()
		{
			return mode;
		}

		PotionComponent next()
		{
			return next;
		}

		/**
		 * @return true if the lever for {@code component} may be pulled under lever click protection
		 */
		boolean allows(PotionComponent component)
		{
			if (mode == LeverMode.FREE)
				return true;

			return mode == LeverMode.PULL && next == component;
		}
	}

	private MixGuidance()
	{
	}

	/**
	 * Maps a {@code MM_LAB_MIXER_SLOT_*} varbit value (1 mox, 2 aga, 3 lye) to its component.
	 *
	 * @return the component, or null for an empty slot or unknown value
	 */
	static PotionComponent componentFromSlotValue(int value)
	{
		if (value < 1 || value > PotionComponent.ENTRIES.length)
			return null;

		return PotionComponent.ENTRIES[value - 1];
	}

	/**
	 * Fills the vessel's empty slots, in order, with lever pulls the server has not reflected yet, so a quick
	 * second click is judged against the vessel it will actually hit.
	 *
	 * @param pending lever pulls not yet shown in the mixer varbits, oldest first
	 * @return a copy of {@code mixerSlots} with the pending pastes added
	 */
	static int[] withPendingPulls(int[] mixerSlots, List<PotionComponent> pending)
	{
		int[] slots = mixerSlots.clone();
		int next = 0;
		for (int i = 0; i < slots.length && next < pending.size(); i++)
		{
			if (slots[i] == 0)
			{
				slots[i] = pending.get(next).ordinal() + 1;
				next++;
			}
		}

		return slots;
	}

	/**
	 * @return true when the vessel holds three pastes (or the game flags it ready) and should be mixed
	 */
	static boolean vesselFull(int[] mixerSlots, int vesselReadyValue)
	{
		if (vesselReadyValue != 0)
			return true;

		for (int slot : mixerSlots)
		{
			if (slot == 0)
				return false;
		}

		return true;
	}

	/**
	 * @return true when the vessel holds no paste and no ready mix
	 */
	static boolean vesselEmpty(int[] mixerSlots, int vesselReadyValue)
	{
		if (vesselReadyValue != 0)
			return false;

		for (int slot : mixerSlots)
		{
			if (slot != 0)
				return false;
		}

		return true;
	}

	/**
	 * @return true if the order is part of the plan: no recommendation is active, or the chosen strategy recommends it
	 */
	static boolean planned(PotionOrder order, Set<Integer> recommendedSlots)
	{
		return recommendedSlots == null || recommendedSlots.isEmpty() || recommendedSlots.contains(order.idx());
	}

	/**
	 * Picks the first planned, unfulfilled order (in display order) that no potion on hand already covers.
	 * Each potion on hand covers at most one order, so duplicate orders each need their own potion.
	 *
	 * @param onHand unfinished potions in the inventory, in a station, or ready in the vessel, by type
	 * @return the order to mix next, or null if every planned order is covered
	 */
	static PotionOrder nextOrderToMix(List<PotionOrder> orders, Set<Integer> recommendedSlots,
			Map<PotionType, Integer> onHand)
	{
		Map<PotionType, Integer> remaining = new EnumMap<>(PotionType.class);
		remaining.putAll(onHand);
		for (PotionOrder order : orders)
		{
			if (order.fulfilled() || !planned(order, recommendedSlots))
				continue;

			int count = remaining.getOrDefault(order.potionType(), 0);
			if (count > 0)
			{
				remaining.put(order.potionType(), count - 1);
				continue;
			}

			return order;
		}

		return null;
	}

	/**
	 * Picks the open order whose station should take the unfinished potion in the inventory: a planned order first,
	 * then a skipped one, each in display order. Without the planned pass, a skipped order of the same potion type
	 * listed first would claim the potion and leave the planned order open.
	 *
	 * @param inInventory whether an unfinished potion of the type is in the inventory
	 * @return the order, or null if no open order's potion is in the inventory
	 */
	static PotionOrder orderToProcess(List<PotionOrder> orders, Set<Integer> recommendedSlots,
			Predicate<PotionType> inInventory)
	{
		for (boolean wantPlanned : new boolean[]{true, false})
		{
			for (PotionOrder order : orders)
			{
				if (!order.fulfilled() && planned(order, recommendedSlots) == wantPlanned
						&& inInventory.test(order.potionType()))
					return order;
			}
		}

		return null;
	}

	/**
	 * Decides the next lever from the target recipe and the pastes already in the vessel.
	 * Pastes are matched as a multiset, so the vessel order does not matter; the next lever follows the
	 * recipe's displayed order.
	 *
	 * @param target the potion being mixed, or null when nothing needs mixing
	 */
	static LeverState leverState(PotionType target, int[] mixerSlots, int vesselReadyValue)
	{
		if (vesselFull(mixerSlots, vesselReadyValue))
			return LeverState.BLOCKED;

		if (target == null)
			return vesselEmpty(mixerSlots, vesselReadyValue) ? LeverState.BLOCKED : LeverState.FREE;

		List<PotionComponent> needed = new ArrayList<>(List.of(target.components()));
		for (int slot : mixerSlots)
		{
			if (slot == 0)
				continue;

			PotionComponent component = componentFromSlotValue(slot);
			if (component == null || !needed.remove(component))
				return LeverState.FREE;
		}

		return LeverState.pull(needed.get(0));
	}

	/**
	 * Identifies the potion the vessel will produce: the game's ready flag if set, otherwise the three pastes.
	 *
	 * @return the potion, or null if the vessel is not full
	 */
	static PotionType vesselPotion(int[] mixerSlots, int vesselReadyValue)
	{
		PotionType ready = PotionType.fromIdx(vesselReadyValue - 1);
		if (ready != null)
			return ready;

		int[] counts = new int[PotionComponent.ENTRIES.length];
		for (int slot : mixerSlots)
		{
			PotionComponent component = componentFromSlotValue(slot);
			if (component == null)
				return null;

			counts[component.ordinal()]++;
		}

		for (PotionType type : PotionType.TYPES)
		{
			int[] recipe = new int[PotionComponent.ENTRIES.length];
			for (PotionComponent component : type.components())
				recipe[component.ordinal()]++;

			if (Arrays.equals(recipe, counts))
				return type;
		}

		return null;
	}

	/**
	 * True if the mix fills an unfulfilled order (skipped ones included) that no potion on hand already covers.
	 *
	 * @param onHand unfinished potions in the inventory or a station, by type, excluding the vessel itself
	 */
	static boolean mixMatchesOpenOrder(PotionType mix, List<PotionOrder> orders, Map<PotionType, Integer> onHand)
	{
		return mixMatchesPlannedOrder(mix, orders, null, onHand);
	}

	/**
	 * Like {@link #mixMatchesOpenOrder}, counting only the orders the player plans to make: a mix that only a skipped
	 * order would take is one to correct, not to mix.
	 *
	 * @param recommendedSlots the planned order slots; null or empty plans every order
	 */
	static boolean mixMatchesPlannedOrder(PotionType mix, List<PotionOrder> orders, Set<Integer> recommendedSlots,
			Map<PotionType, Integer> onHand)
	{
		if (mix == null)
			return false;

		int open = 0;
		for (PotionOrder order : orders)
		{
			if (!order.fulfilled() && order.potionType() == mix && planned(order, recommendedSlots))
				open++;
		}

		return open > onHand.getOrDefault(mix, 0);
	}

	/**
	 * True when every planned order is fulfilled and the inventory still holds a finished potion for each.
	 *
	 * @param finishedOnHand finished potions in the inventory, by type
	 */
	static boolean readyToDeliver(List<PotionOrder> orders, Set<Integer> recommendedSlots,
			Map<PotionType, Integer> finishedOnHand)
	{
		Map<PotionType, Integer> remaining = new EnumMap<>(PotionType.class);
		remaining.putAll(finishedOnHand);
		boolean anyPlanned = false;
		for (PotionOrder order : orders)
		{
			if (!planned(order, recommendedSlots))
				continue;

			anyPlanned = true;
			int count = remaining.getOrDefault(order.potionType(), 0);
			if (!order.fulfilled() || count == 0)
				return false;

			remaining.put(order.potionType(), count - 1);
		}

		return anyPlanned;
	}
}

package com.oveduumnakal.anothermixology;

import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.font.FontRenderContext;
import java.util.HashMap;
import java.util.Map;

/**
 * The monospace fonts the rewards panel draws its numbers in: the times and percents of the reward rows, sized to the
 * row text by {@link #matching}, and the labels of the resin bars. Every digit is the same width, so numbers line up
 * from row to row.
 */
final class NumberFont
{
	static final Font BAR = new Font(Font.MONOSPACED, Font.PLAIN, 11);

	private static final Font BASE = new Font(Font.MONOSPACED, Font.PLAIN, 1);
	private static final int LARGEST_SIZE = 32;

	/** The monospace font already worked out for each text font. */
	private static final Map<Font, Font> MATCHED = new HashMap<>();

	private NumberFont()
	{
	}

	/**
	 * Returns the largest monospace font whose digits stand no taller than {@code font}'s, so numbers sit level with
	 * text drawn in {@code font}.
	 */
	static Font matching(Graphics2D graphics, Font font)
	{
		return MATCHED.computeIfAbsent(font, text ->
		{
			var frc = graphics.getFontRenderContext();
			int target = digitHeight(text, frc);
			var best = BASE.deriveFont(1f);
			for (int size = 2; size <= LARGEST_SIZE; size++)
			{
				var candidate = BASE.deriveFont((float) size);
				if (digitHeight(candidate, frc) > target)
					break;

				best = candidate;
			}

			return best;
		});
	}

	private static int digitHeight(Font font, FontRenderContext frc)
	{
		return font.createGlyphVector(frc, "0")
				.getPixelBounds(frc, 0, 0).height;
	}

	/** Runs {@code draw} with {@code font} set and text smoothed, then puts back the graphics' font and smoothing. */
	static void with(Graphics2D graphics, Font font, Runnable draw)
	{
		var oldFont = graphics.getFont();
		var oldSmoothing = graphics.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		graphics.setFont(font);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		try
		{
			draw.run();
		}
		finally
		{
			graphics.setFont(oldFont);
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
					oldSmoothing != null ? oldSmoothing : RenderingHints.VALUE_TEXT_ANTIALIAS_DEFAULT);
		}
	}
}

package com.oveduumnakal.anothermixology;

/**
 * The three visible orders as a recommendation policy sees them: each slot's potion and modifier, whether a digweed
 * already improved the slot's potion, and how many digweed the player holds. Arrays are indexed by order slot; an
 * entry is null (or false) when it is not known.
 */
public final class OrderSet
{
	private final PotionType[] orders;
	private final PotionModifier[] modifiers;
	private final boolean[] improved;
	private final int digweed;

	public OrderSet(PotionType[] orders, PotionModifier[] modifiers, boolean[] improved, int digweed)
	{
		this.orders = orders;
		this.modifiers = modifiers;
		this.improved = improved;
		this.digweed = digweed;
	}

	/** Returns the orders with no modifier, improvement or digweed known. */
	public static OrderSet of(PotionType[] orders)
	{
		return new OrderSet(orders, new PotionModifier[orders.length], new boolean[orders.length], 0);
	}

	public PotionType[] orders()
	{
		return orders;
	}

	public PotionModifier[] modifiers()
	{
		return modifiers;
	}

	/** Returns, per slot, whether a digweed already doubled that order's potion. */
	public boolean[] improved()
	{
		return improved;
	}

	/** Returns how many digweed the player holds, ready to double a potion. */
	public int digweed()
	{
		return digweed;
	}
}

package com.oveduumnakal.anothermixology;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.Map;
import java.util.Set;
import java.util.WeakHashMap;
import java.util.function.UnaryOperator;
import javax.inject.Inject;

import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

/**
 * Stands in for the game's potion orders panel while it is hidden. It shows one row per order, with the station icon,
 * the name coloured by the paste each part stands for, and the recipe or "done!", then the paste left in the hopper
 * and, when enabled, the resin earned.
 */
public class OrdersPanelOverlay extends Overlay
{
	private static final int PADDING = 4;
	private static final int ICON_SIZE = 16;
	private static final int ROW_HEIGHT = 20;
	private static final int SMALL_ROW_HEIGHT = 16;
	private static final int AMOUNT_ROW_HEIGHT = 20;
	private static final int BLOCK_SIZE = 9;
	private static final int BLOCK_GAP = 2;

	/** How long the digweed icon stays on, then off, while it flashes. */
	private static final long DIGWEED_FLASH_MILLIS = 400;
	private static final int ICON_GAP = 4;
	private static final int NAME_RECIPE_GAP = 8;
	private static final int MIN_WIDTH = 200;
	private static final int DIVIDER_GAP = 4;
	private static final int AMOUNT_ICON_SIZE = 16;
	private static final Color DONE_COLOR = new Color(0, 255, 0);
	private static final Color DIVIDER_COLOR = new Color(255, 255, 255, 90);
	private static final int[] PASTE_ITEM_IDS = {ItemID.MM_MOX_PASTE, ItemID.MM_AGA_PASTE, ItemID.MM_LYE_PASTE};

	private final AnotherMixologyPlugin plugin;
	private final AnotherMixologyConfig config;
	private final SpriteManager spriteManager;
	private final ItemManager itemManager;

	/** Scaled station icons, keyed by the game's sprite, so each is resized once instead of every frame. */
	private final Map<BufferedImage, BufferedImage> scaledStationIcons =
			Collections.synchronizedMap(new WeakHashMap<>());

	/** Scaled paste and resin icons, keyed by the source image. */
	private final Map<BufferedImage, BufferedImage> scaledAmountIcons =
			Collections.synchronizedMap(new WeakHashMap<>());

	/** Item images whose loading is watched, so a copy scaled before the image loaded is dropped once it has. */
	private final Set<BufferedImage> watchedImages = Collections.newSetFromMap(
			Collections.synchronizedMap(new WeakHashMap<>()));

	/** The digweed leaf, drawn again when the digweed colour changes. */
	private BufferedImage digweedIcon;
	private Color digweedIconColor;

	@Inject
	OrdersPanelOverlay(AnotherMixologyPlugin plugin, AnotherMixologyConfig config, SpriteManager spriteManager,
			ItemManager itemManager)
	{
		this.itemManager = itemManager;
		this.plugin = plugin;
		this.config = config;
		this.spriteManager = spriteManager;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	/** Draws the panel, or nothing when the game's own panel is showing or the player is outside the lab. */
	@Override
	public Dimension render(Graphics2D graphics)
	{
		var orders = plugin.potionOrders();

		if (!config.hideOrdersPanel() || !plugin.isOrdersPanelVisible())
			return null;

		var nameFont = FontManager.getRunescapeFont();
		var smallFont = FontManager.getRunescapeSmallFont();
		int nameWidth = 0;
		for (var order : orders)
			nameWidth = Math.max(nameWidth, nameWidth(graphics, nameFont, order.potionType()));

		graphics.setFont(smallFont);
		int recipeWidth = graphics.getFontMetrics().stringWidth("(done!)");
		int digweedTarget = plugin.digweedTargetSlot();
		boolean digweedShown = digweedTarget >= 0 || orders.stream().anyMatch(PotionOrder::improved);
		int digweedWidth = digweedShown ? ICON_GAP + ICON_SIZE : 0;
		int width = Math.max(MIN_WIDTH,
				PADDING * 2 + ICON_SIZE + ICON_GAP + nameWidth + NAME_RECIPE_GAP + recipeWidth + digweedWidth);
		int rows = config.displayResin() ? 2 : 1;
		int height = PADDING * 2 + SMALL_ROW_HEIGHT + ROW_HEIGHT * orders.size() + DIVIDER_GAP * 2
				+ AMOUNT_ROW_HEIGHT * rows;

		graphics.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		graphics.fillRect(0, 0, width, height);

		int y = PADDING + graphics.getFontMetrics().getAscent();
		drawText(graphics, "Potion Orders", PADDING, y, Color.WHITE);
		y += SMALL_ROW_HEIGHT - graphics.getFontMetrics().getAscent();

		var recommended = plugin.recommendedSlots();
		for (var order : orders)
		{
			boolean skipped = recommended != null && !order.fulfilled() && !recommended.contains(order.idx());
			drawOrder(graphics, order, skipped, y, nameFont, smallFont, nameWidth);
			drawDigweed(graphics, order, order.idx() == digweedTarget, y,
					PADDING + ICON_SIZE + ICON_GAP + nameWidth + NAME_RECIPE_GAP + recipeWidth + ICON_GAP);
			y += ROW_HEIGHT;
		}

		y += DIVIDER_GAP;
		graphics.setColor(DIVIDER_COLOR);
		graphics.drawLine(PADDING, y, width - PADDING, y);
		y += DIVIDER_GAP;

		graphics.setFont(smallFont);
		drawAmounts(graphics, y, width, true);
		if (config.displayResin())
			drawAmounts(graphics, y + AMOUNT_ROW_HEIGHT, width, false);

		return new Dimension(width, height);
	}

	private int nameWidth(Graphics2D graphics, Font font, PotionType potionType)
	{
		var metrics = graphics.getFontMetrics(font);
		int total = 0;
		for (var part : potionType.nameParts())
			total += metrics.stringWidth(part);

		return total;
	}

	private void drawOrder(Graphics2D graphics, PotionOrder order, boolean skipped, int top, Font nameFont,
			Font smallFont, int nameWidth)
	{
		var icon = stationIcon(order.idx());
		if (icon != null)
			drawIcon(graphics, icon, PADDING, top + (ROW_HEIGHT - icon.getHeight()) / 2);

		graphics.setFont(nameFont);
		int baseline = top + (ROW_HEIGHT + graphics.getFontMetrics().getAscent()) / 2 - 2;
		int x = PADDING + ICON_SIZE + ICON_GAP;
		var parts = order.potionType().nameParts();
		var components = order.potionType().components();
		for (int i = 0; i < parts.length; i++)
		{
			var color = skipped ? skipColor() : plugin.effectiveComponentColor(components[i]);
			drawText(graphics, parts[i], x, baseline, color);
			x += graphics.getFontMetrics().stringWidth(parts[i]);
		}

		graphics.setFont(smallFont);
		x = PADDING + ICON_SIZE + ICON_GAP + nameWidth + NAME_RECIPE_GAP;
		if (order.fulfilled())
			drawText(graphics, "(done!)", x, baseline, DONE_COLOR);
		else
			drawRecipe(graphics, order.potionType(), x, baseline, skipped);
	}

	/**
	 * Draws the digweed icon after an order's recipe: solid once a digweed improved the order's potion, flashing while
	 * the held digweed should go on it.
	 */
	private void drawDigweed(Graphics2D graphics, PotionOrder order, boolean target, int top, int x)
	{
		boolean flashOn = System.currentTimeMillis() / DIGWEED_FLASH_MILLIS % 2 == 0;
		if (!order.improved() && !(target && flashOn))
			return;

		var color = config.digweedHighlightColor();
		if (digweedIcon == null || !color.equals(digweedIconColor))
		{
			digweedIcon = DigweedIcon.create(ICON_SIZE, color);
			digweedIconColor = color;
		}

		drawIcon(graphics, digweedIcon, x, top + (ROW_HEIGHT - ICON_SIZE) / 2);
	}

	/** Returns the station icon for an order slot, scaled down to fit the row, or null before the game's is read. */
	private BufferedImage stationIcon(int idx)
	{
		int spriteId = plugin.orderSpriteId(idx);
		if (spriteId < 0)
			return null;

		var sprite = spriteManager.getSprite(spriteId, 0);
		if (sprite == null || sprite.getHeight() <= ICON_SIZE)
			return sprite;

		return scaled(scaledStationIcons, sprite,
				image -> ImageUtil.resizeImage(image, image.getWidth() * ICON_SIZE / image.getHeight(), ICON_SIZE,
						true));
	}

	/** Draws the mox, aga and lye amounts as an icon and the amount, each in its component's colour. */
	private void drawAmounts(Graphics2D graphics, int top, int width, boolean paste)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		int cell = (width - PADDING * 2) / PotionComponent.ENTRIES.length;
		int baseline = top + AMOUNT_ROW_HEIGHT / 2 + (metrics.getAscent() - metrics.getDescent()) / 2;

		for (var component : PotionComponent.ENTRIES)
		{
			int amount = paste ? plugin.pasteAmount(component) : plugin.resinAmount(component);
			var text = String.valueOf(amount);
			var icon = paste ? pasteIcon(component) : resinIcon(component);
			int x = PADDING + cell * component.ordinal();
			if (icon != null)
			{
				drawIcon(graphics, icon, x, top + (AMOUNT_ROW_HEIGHT - icon.getHeight()) / 2);
				x += icon.getWidth() + ICON_GAP;
			}

			drawText(graphics, text, x, baseline, plugin.effectiveComponentColor(component));
		}
	}

	private BufferedImage pasteIcon(PotionComponent component)
	{
		return fit(itemManager.getImage(PASTE_ITEM_IDS[component.ordinal()]));
	}

	private BufferedImage resinIcon(PotionComponent component)
	{
		return fit(spriteManager.getSprite(component.spriteId(), 0));
	}

	/** Returns the image scaled down to fit the amount row, or null when it is not loaded yet. */
	private BufferedImage fit(BufferedImage image)
	{
		if (image == null || image.getHeight() <= AMOUNT_ICON_SIZE)
			return image;

		return scaled(scaledAmountIcons, image,
				source -> ImageUtil.resizeImage(source, AMOUNT_ICON_SIZE, AMOUNT_ICON_SIZE, true));
	}

	/**
	 * Returns the cached scaled copy of an image, scaling it on first use. An item image that is still loading is
	 * scaled blank, so its copy is dropped when it finishes loading and scaled again on the next frame.
	 */
	private BufferedImage scaled(Map<BufferedImage, BufferedImage> cache, BufferedImage source,
			UnaryOperator<BufferedImage> resize)
	{
		var cached = cache.get(source);
		if (cached != null)
			return cached;

		var result = resize.apply(source);
		cache.put(source, result);
		if (source instanceof AsyncBufferedImage && watchedImages.add(source))
			((AsyncBufferedImage) source).onLoaded(() -> cache.remove(source));

		return result;
	}

	private Color skipColor()
	{
		return config.skipColor();
	}

	/**
	 * Draws three colour blocks, or the three resin letters with Use Letters on. A skipped order is drawn all in the
	 * skip colour.
	 */
	private void drawRecipe(Graphics2D graphics, PotionType potionType, int x, int baseline, boolean skipped)
	{
		var metrics = graphics.getFontMetrics();

		for (var component : potionType.components())
		{
			var color = skipped ? skipColor() : plugin.effectiveComponentColor(component);

			if (!config.useLetters())
			{
				graphics.setColor(color);
				graphics.fillRect(x, baseline - BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
				x += BLOCK_SIZE + BLOCK_GAP;
			}
			else
			{
				var letter = String.valueOf(component.character());
				drawText(graphics, letter, x, baseline, color);
				x += metrics.stringWidth(letter);
			}
		}
	}

	private void drawText(Graphics2D graphics, String text, int x, int baseline, Color color)
	{
		graphics.setColor(color);
		graphics.drawString(text, x, baseline);
	}

	private void drawIcon(Graphics2D graphics, BufferedImage image, int x, int y)
	{
		graphics.drawImage(image, x, y, null);
	}
}

package com.oveduumnakal.anothermixology;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.font.FontRenderContext;

import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * Progress bar with readable text. Mirrors the interface of {@code ProgressBarComponent}, but draws each label in
 * two parts: over the filled part of the bar and over the empty part, each in light or dark text, whichever stands out
 * more against that part's colour. A label the fill edge crosses is drawn partly dark and partly light.
 */
class OutlinedProgressBarComponent implements LayoutableRenderableEntity
{
	private static final int BAR_HEIGHT = 16;
	private static final int TEXT_PADDING = 4;

	private double value = 0.0;
	private String leftLabel = "";
	private String centerLabel = "";
	private String rightLabel = "";
	private Color foregroundColor = Color.GREEN;
	private Color backgroundColor = new Color(61, 56, 49);
	/** Light text, with a black outline. */
	static final Color LIGHT_TEXT = Color.WHITE;

	/** Dark text, drawn without an outline or shadow. */
	static final Color DARK_TEXT = new Color(16, 16, 16);

	/** Background luminance above which dark text stands out more than light (WCAG contrast crossover). */
	private static final double DARK_TEXT_LUMINANCE = 0.179;

	private Point preferredLocation = new Point();
	private Dimension preferredSize = new Dimension(ComponentConstants.STANDARD_WIDTH, BAR_HEIGHT);
	private final Rectangle bounds = new Rectangle();

	void setValue(double value)
	{
		this.value = Math.max(0, Math.min(100, value));
	}

	void setLeftLabel(String s)
	{
		this.leftLabel = s == null ? "" : s;
	}

	void setCenterLabel(String s)
	{
		this.centerLabel = s == null ? "" : s;
	}

	void setRightLabel(String s)
	{
		this.rightLabel = s == null ? "" : s;
	}

	void setForegroundColor(Color c)
	{
		this.foregroundColor = c;
	}

	void setBackgroundColor(Color c)
	{
		this.backgroundColor = c;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int x = preferredLocation.x;
		int y = preferredLocation.y;
		int width = preferredSize.width;
		int height = preferredSize.height > 0 ? preferredSize.height : BAR_HEIGHT;

		graphics.setColor(backgroundColor);
		graphics.fillRect(x, y, width, height);

		int fgWidth = (int) (width * value / 100.0);
		graphics.setColor(foregroundColor);
		graphics.fillRect(x, y, fgWidth, height);

		var filled = new Rectangle(x, y, fgWidth, height);
		var empty = new Rectangle(x + fgWidth, y, width - fgWidth, height);
		NumberFont.with(graphics, NumberFont.BAR, () -> drawLabels(graphics, x, y, width, height, filled, empty));

		bounds.setBounds(x, y, width, height);
		return new Dimension(width, height);
	}

	private void drawLabels(Graphics2D graphics, int x, int y, int width, int height, Rectangle filled,
			Rectangle empty)
	{
		FontMetrics fm = graphics.getFontMetrics();
		int textY = centeredBaseline(graphics, y, height);
		if (!leftLabel.isEmpty())
			drawLabel(graphics, leftLabel, x + TEXT_PADDING, textY, filled, empty);

		if (!centerLabel.isEmpty())
		{
			int w = fm.stringWidth(centerLabel);
			drawLabel(graphics, centerLabel, x + (width - w) / 2, textY, filled, empty);
		}

		if (!rightLabel.isEmpty())
		{
			int w = fm.stringWidth(rightLabel);
			drawLabel(graphics, rightLabel, x + width - w - TEXT_PADDING, textY, filled, empty);
		}
	}

	/**
	 * Finds the baseline that centres the labels vertically in the bar. A font's ascent can include empty
	 * rows above the glyphs, so it centres on the pixel bounds of a digit (the labels are quantities) instead;
	 * every label shares that baseline. The one-pixel outline grows the text equally up and down.
	 *
	 * @param graphics the graphics, with the label font set
	 * @param y        top of the bar
	 * @param height   height of the bar
	 * @return the baseline y for the labels
	 */
	static int centeredBaseline(Graphics2D graphics, int y, int height)
	{
		FontRenderContext frc = graphics.getFontRenderContext();
		Rectangle digit = graphics.getFont()
			.createGlyphVector(frc, "0")
			.getPixelBounds(frc, 0, 0);
		return y + (height - digit.height) / 2 - digit.y;
	}

	/** Draws a label twice, clipped to the filled and the empty part, in the text colour that suits each. */
	private void drawLabel(Graphics2D graphics, String text, int x, int y, Rectangle filled, Rectangle empty)
	{
		var clip = graphics.getClip();
		graphics.clip(filled);
		drawText(graphics, text, x, y, textColorOn(foregroundColor));
		graphics.setClip(clip);
		graphics.clip(empty);
		drawText(graphics, text, x, y, textColorOn(backgroundColor));
		graphics.setClip(clip);
	}

	/** Draws light text with a black outline, and dark text plain, since a shadow would only blur it. */
	private static void drawText(Graphics2D graphics, String text, int x, int y, Color color)
	{
		if (color != LIGHT_TEXT)
		{
			graphics.setColor(color);
			graphics.drawString(text, x, y);
			return;
		}

		TextComponent t = new TextComponent();
		t.setText(text);
		t.setColor(color);
		t.setOutline(true);
		t.setPosition(new Point(x, y));
		t.render(graphics);
	}

	/** Returns light or dark text, whichever contrasts more with the background colour. */
	static Color textColorOn(Color background)
	{
		return luminance(background) > DARK_TEXT_LUMINANCE ? DARK_TEXT : LIGHT_TEXT;
	}

	/** Returns the colour's relative luminance, from 0 (black) to 1 (white), as WCAG defines it. */
	static double luminance(Color color)
	{
		return 0.2126 * linear(color.getRed()) + 0.7152 * linear(color.getGreen()) + 0.0722 * linear(color.getBlue());
	}

	private static double linear(int channel)
	{
		double c = channel / 255.0;
		return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point preferredLocation)
	{
		this.preferredLocation = preferredLocation;
	}

	@Override
	public void setPreferredSize(Dimension preferredSize)
	{
		this.preferredSize = preferredSize;
	}
}

package com.oveduumnakal.anothermixology;

/** How long the player takes per potion and per delivery, in seconds. */
final class Pace
{
	/**
	 * The fit over 40 order sets of 2026-10-29 lab play: 11.3 seconds per delivery, and 15.5, 18.7 and 15.4 seconds per
	 * Alembic, Retort and Agitator potion, averaged here since every modifier is ordered equally often.
	 */
	static final Pace DEFAULT = new Pace((15.5 + 18.7 + 15.4) / 3, 11.3);

	final double secondsPerPotion;
	final double secondsPerDelivery;

	Pace(double secondsPerPotion, double secondsPerDelivery)
	{
		this.secondsPerPotion = secondsPerPotion;
		this.secondsPerDelivery = secondsPerDelivery;
	}

	@Override
	public boolean equals(Object other)
	{
		if (!(other instanceof Pace))
			return false;

		var pace = (Pace) other;
		return pace.secondsPerPotion == secondsPerPotion && pace.secondsPerDelivery == secondsPerDelivery;
	}

	@Override
	public int hashCode()
	{
		return Double.hashCode(secondsPerPotion) * 31 + Double.hashCode(secondsPerDelivery);
	}
}

package com.oveduumnakal.anothermixology;

import java.util.ArrayList;
import java.util.List;

/**
 * Measures the player's pace from the order sets delivered this session: a least-squares line through each set's
 * time against its potion count gives the seconds per potion (slope) and per delivery (intercept). Until
 * {@link #MIN_SETS} sets are seen, or when the fit makes no sense, it answers {@link Pace#DEFAULT}.
 */
final class PaceTracker
{
	static final int MIN_SETS = 10;

	/** Sets slower than this are breaks or detours, not play, and are left out. */
	static final double MAX_SET_SECONDS = 100;

	private final List<double[]> sets = new ArrayList<>();

	/** Records one delivered set: how long it took from the previous delivery and how many potions it held. */
	void addSet(double seconds, int potions)
	{
		if (potions > 0 && seconds > 0 && seconds <= MAX_SET_SECONDS)
			sets.add(new double[]{potions, seconds});
	}

	Pace pace()
	{
		int n = sets.size();
		if (n < MIN_SETS)
			return Pace.DEFAULT;

		double sumX = 0;
		double sumY = 0;
		double sumXx = 0;
		double sumXy = 0;
		for (double[] set : sets)
		{
			sumX += set[0];
			sumY += set[1];
			sumXx += set[0] * set[0];
			sumXy += set[0] * set[1];
		}

		double spread = n * sumXx - sumX * sumX;
		if (spread == 0)
			return Pace.DEFAULT;

		double perPotion = (n * sumXy - sumX * sumY) / spread;
		double perDelivery = (sumY - perPotion * sumX) / n;
		if (perPotion <= 0 || perDelivery < 0)
			return Pace.DEFAULT;

		return new Pace(perPotion, perDelivery);
	}

	void clear()
	{
		sets.clear();
	}
}

package com.oveduumnakal.anothermixology;

/**
 * Counts the time spent playing, so the reward times count down only while the player works. It runs from an action
 * until {@link #IDLE_MILLIS} after the last one, which covers the short pauses of play, and then stops. Times are
 * {@link System#currentTimeMillis()} values passed in, so it can be unit tested.
 */
final class PlayClock
{
	/** How long after their last action the player still counts as playing. */
	static final long IDLE_MILLIS = 6_000;

	/** The play counted before the current run. */
	private long counted;

	/** When the current run started; -1 before the first action. */
	private long runningSince = -1;

	private long lastActive;

	/** Records that the player did something at {@code now}, starting the clock again if they were idle. */
	void active(long now)
	{
		if (runningSince < 0 || now > lastActive + IDLE_MILLIS)
		{
			counted = played(now);
			runningSince = now;
		}

		lastActive = now;
	}

	/** Returns the milliseconds played up to {@code now}. */
	long played(long now)
	{
		if (runningSince < 0)
			return counted;

		return counted + Math.max(0, Math.min(now, lastActive + IDLE_MILLIS) - runningSince);
	}
}

package com.oveduumnakal.anothermixology;

import java.util.Comparator;

/** Orderings for the potion orders shown in the interface. */
public class PotionComparators
{
	/**
	 * Orders by modifier, crystalised before homogenous before concentrated, then by potion type name.
	 * Concentrate comes last to avoid misclicks on the retort.
	 */
	public static Comparator<PotionOrder> byStation()
	{
		return Comparator.comparingInt((PotionOrder order) ->
		{
			switch (order.potionModifier())
			{
				case CRYSTALISED:
					return 0;
				case HOMOGENOUS:
					return 1;
				case CONCENTRATED:
					return 2;
				default:
					return Integer.MAX_VALUE;
			}
		})
				.thenComparing(order -> order.potionType().name());
	}

	/** Orders by modifier, crystalised then concentrated then homogenous (the "Shortest Path" sorting option). */
	public static Comparator<PotionOrder> shortestPath()
	{
		return Comparator.comparing(order ->
		{
			switch (order.potionModifier())
			{
				case CRYSTALISED:
					return 1;
				case CONCENTRATED:
					return 2;
				case HOMOGENOUS:
					return 3;
				default:
					throw new IllegalStateException("Unexpected value: " + order.potionModifier().toString());
			}
		});
	}
}

