package com.oveduumnakal.anothermixology;

import java.util.ArrayList;
import java.util.List;

/**
 * The order the tracked rewards are listed and bought in, saved as a comma separated list of {@link RewardItem}
 * names. A reward goes to the bottom when it is ticked and leaves when it is unticked; the player moves one up or
 * down from the rewards panel's right-click menu. Free of client state so it can be unit tested.
 */
final class RewardPriority
{
	static final String CONFIG_KEY = "rewardPriority";

	private RewardPriority()
	{
	}

	/** Reads a saved order, skipping names that are not rewards. */
	static List<RewardItem> parse(String saved)
	{
		List<RewardItem> order = new ArrayList<>();
		if (saved == null)
			return order;

		for (String name : saved.split(","))
		{
			for (RewardItem item : RewardItem.values())
			{
				if (item.name().equals(name.trim()) && !order.contains(item))
					order.add(item);
			}
		}

		return order;
	}

	static String format(List<RewardItem> order)
	{
		List<String> names = new ArrayList<>();
		for (RewardItem item : order)
			names.add(item.name());

		return String.join(",", names);
	}

	/**
	 * Brings a saved order up to date with the ticked rewards: unticked ones are dropped and newly ticked ones are
	 * added at the bottom, in the order given.
	 */
	static List<RewardItem> reconcile(List<RewardItem> order, List<RewardItem> ticked)
	{
		List<RewardItem> result = new ArrayList<>(order);
		result.retainAll(ticked);
		for (RewardItem item : ticked)
		{
			if (!result.contains(item))
				result.add(item);
		}

		return result;
	}

	/** Returns the selections sorted into the saved order; any the order lacks keep their place after it. */
	static List<Goal.Selection> sort(List<Goal.Selection> selections, List<RewardItem> order)
	{
		List<Goal.Selection> sorted = new ArrayList<>();
		for (RewardItem item : order)
		{
			for (Goal.Selection selection : selections)
			{
				if (selection.item == item)
					sorted.add(selection);
			}
		}

		for (Goal.Selection selection : selections)
		{
			if (!order.contains(selection.item))
				sorted.add(selection);
		}

		return sorted;
	}

	/** Returns the order with the reward moved one place up (-1) or down (+1); unchanged at either end. */
	static List<RewardItem> move(List<RewardItem> order, RewardItem item, int direction)
	{
		List<RewardItem> result = new ArrayList<>(order);
		int from = result.indexOf(item);
		int to = from + direction;
		if (from < 0 || to < 0 || to >= result.size())
			return result;

		result.set(from, result.get(to));
		result.set(to, item);
		return result;
	}
}

package com.oveduumnakal.anothermixology;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;

import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * One row of the rewards panel: the reward's icon and name, its progress percent on the right, and between them its
 * estimated time, centred in a slot every row shares so the times form one column. A row without a time leaves the
 * slot out.
 */
class RewardRowComponent implements LayoutableRenderableEntity
{
	static final int HEIGHT = 20;
	static final int ICON_COLUMN = 24;
	static final int GAP = 8;

	/** The widest time and percent; every row's time slot and percent column are this wide. */
	static final String WIDEST_TIME = "00h 00m 00s";
	static final String WIDEST_PERCENT = "100%";
	private static final int ICON_HEIGHT = 18;

	private final BufferedImage icon;
	private final String label;
	private final String time;
	private final Color timeColor;
	private final String percent;
	private final Color percentColor;
	private final int labelColumn;

	private Point preferredLocation = new Point();
	private Dimension preferredSize = new Dimension(0, HEIGHT);
	private final Rectangle bounds = new Rectangle();

	/**
	 * @param icon        the reward icon, or null for a row without one
	 * @param time        the estimated time, or null for a row without the time column
	 * @param labelColumn width of the name column, shared by every row so the times line up
	 */
	RewardRowComponent(BufferedImage icon, String label, String time, Color timeColor, String percent,
			Color percentColor, int labelColumn)
	{
		this.icon = icon;
		this.label = label;
		this.time = time;
		this.timeColor = timeColor;
		this.percent = percent;
		this.percentColor = percentColor;
		this.labelColumn = labelColumn;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int x = preferredLocation.x;
		int y = preferredLocation.y;
		int width = preferredSize.width;
		int baseline = OutlinedProgressBarComponent.centeredBaseline(graphics, y, HEIGHT);

		if (icon != null && icon.getHeight() > 0)
		{
			int iconWidth = icon.getWidth() * ICON_HEIGHT / icon.getHeight();
			graphics.drawImage(icon, x + (ICON_COLUMN - iconWidth) / 2, y + (HEIGHT - ICON_HEIGHT) / 2, iconWidth,
					ICON_HEIGHT, null);
		}

		int labelX = icon != null ? x + ICON_COLUMN : x;
		drawText(graphics, label, labelX, baseline, Color.WHITE);
		NumberFont.with(graphics, NumberFont.matching(graphics, graphics.getFont()), () ->
		{
			var metrics = graphics.getFontMetrics();
			int numberBaseline = OutlinedProgressBarComponent.centeredBaseline(graphics, y, HEIGHT);
			if (time != null)
			{
				int labelEnd = x + ICON_COLUMN + labelColumn;
				int percentStart = x + width - metrics.stringWidth(WIDEST_PERCENT);
				int slotWidth = metrics.stringWidth(WIDEST_TIME);
				int slotX = labelEnd + (percentStart - labelEnd - slotWidth) / 2;
				int timeX = slotX + (slotWidth - metrics.stringWidth(time)) / 2;
				drawText(graphics, time, timeX, numberBaseline, timeColor);
			}

			drawText(graphics, percent, x + width - metrics.stringWidth(percent), numberBaseline, percentColor);
		});

		bounds.setBounds(x, y, width, HEIGHT);
		return new Dimension(width, HEIGHT);
	}

	private static void drawText(Graphics2D graphics, String text, int x, int y, Color color)
	{
		var component = new TextComponent();
		component.setText(text);
		component.setColor(color);
		component.setPosition(new Point(x, y));
		component.render(graphics);
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point preferredLocation)
	{
		this.preferredLocation = preferredLocation;
	}

	@Override
	public void setPreferredSize(Dimension preferredSize)
	{
		this.preferredSize = preferredSize;
	}
}

package com.oveduumnakal.anothermixology;

import java.util.ArrayList;
import java.util.List;

/**
 * Builds the rows of the rewards panel: one per tracked reward, then one for all of them together. Each row has the
 * resin target its time estimate aims for and its progress, the share of its resin cost already covered.
 */
final class RewardRows
{
	private RewardRows()
	{
	}

	/** One row of the rewards panel. */
	static final class Row
	{
		/** The reward, or null for the all-rewards row. */
		final RewardItem item;
		final String label;

		/** The resin per colour the time estimate aims for, counted from the player's current resin. */
		final int[] target;
		final double progress;

		Row(RewardItem item, String label, int[] target, double progress)
		{
			this.item = item;
			this.label = label;
			this.target = target;
			this.progress = progress;
		}

		/** True when the player can already afford what this row counts. */
		boolean ready()
		{
			return progress >= 1;
		}
	}

	/**
	 * Returns the reward rows followed by the all-rewards row. With {@link RewardOrder#EACH_ON_ITS_OWN} each reward
	 * counts all the resin on its own; with {@link RewardOrder#IN_ORDER} rewards are bought top to bottom, so each
	 * counts only the resin left after the rewards above it, and its target includes theirs.
	 */
	static List<Row> build(List<Goal.Selection> selections, int[] resin, RewardOrder order)
	{
		List<Row> rows = new ArrayList<>();
		int[] above = new int[3];
		int[] all = new int[3];
		for (var selection : selections)
		{
			int[] cost = new int[3];
			for (var component : PotionComponent.ENTRIES)
				cost[component.ordinal()] = selection.item.componentCost(component) * selection.quantity;

			boolean inOrder = order == RewardOrder.IN_ORDER;
			int[] target = new int[3];
			int[] available = new int[3];
			for (int colour = 0; colour < 3; colour++)
			{
				target[colour] = cost[colour] + (inOrder ? above[colour] : 0);
				available[colour] = resin[colour] - (inOrder ? above[colour] : 0);
				above[colour] += cost[colour];
				all[colour] += cost[colour];
			}

			String label = selection.quantity > 1
					? selection.item.itemName() + " x" + selection.quantity
					: selection.item.itemName();
			rows.add(new Row(selection.item, label, target, progress(available, cost)));
		}

		rows.add(new Row(null, "All Rewards:", all, progress(resin, all)));
		return rows;
	}

	/** Returns the share of the cost covered, summed over the colours, from 0 to 1; 1 when nothing is needed. */
	static double progress(int[] available, int[] cost)
	{
		int covered = 0;
		int total = 0;
		for (int colour = 0; colour < 3; colour++)
		{
			covered += Math.max(0, Math.min(available[colour], cost[colour]));
			total += cost[colour];
		}

		return total == 0 ? 1 : covered / (double) total;
	}

	/** Formats seconds as {@code 08h 53m 09s}. */
	static String formatTime(double seconds)
	{
		long total = Math.round(seconds);
		return String.format("%02dh %02dm %02ds", total / 3600, total / 60 % 60, total % 60);
	}
}

package com.oveduumnakal.anothermixology;

import java.util.Set;

/**
 * Estimates how long reaching a resin target takes. The remaining resin is worked off in chunks: for each chunk, every
 * possible order set is weighted by its in-game chance, the strategy picks its delivery, and that gives each colour's
 * useful resin per second at the player's pace. The colours then shrink at those rates until a colour finishes or the
 * chunk is used up. Within about 1.5 % of the simulated average for the Reagent Pouch from any starting resin.
 */
final class RewardTimeEstimator
{
	/** Resin worked off per step, summed over the colours. */
	private static final double CHUNK = 2000;
	private static final int MAX_STEPS = 1000;
	private static final double[] UNIT_COST = {1, 1, 1};

	private RewardTimeEstimator()
	{
	}

	/**
	 * Returns the estimated seconds to reach the target from the given resin, 0 when it is already reached, or
	 * infinity when the strategy makes no progress.
	 */
	static double seconds(RecommendationStrategy strategy, int[] resin, int[] target, Pace pace)
	{
		double[] deficit = new double[3];
		for (int colour = 0; colour < 3; colour++)
			deficit[colour] = Math.max(target[colour] - resin[colour], 0);

		double seconds = 0;
		for (int step = 0; step < MAX_STEPS && !done(deficit); step++)
		{
			int[] whole = new int[3];
			int[] now = new int[3];
			for (int colour = 0; colour < 3; colour++)
			{
				whole[colour] = (int) Math.ceil(deficit[colour]);
				now[colour] = target[colour] - whole[colour];
			}

			double[] rate = rates(strategy, now, target, whole, pace);
			double total = rate[0] + rate[1] + rate[2];
			if (total <= 0)
				return Double.POSITIVE_INFINITY;

			double dt = CHUNK / total;
			for (int colour = 0; colour < 3; colour++)
			{
				if (deficit[colour] >= 1 && rate[colour] > 0)
					dt = Math.min(dt, deficit[colour] / rate[colour]);
			}

			for (int colour = 0; colour < 3; colour++)
				deficit[colour] = Math.max(0, deficit[colour] - rate[colour] * dt);

			seconds += dt;
		}

		return seconds;
	}

	private static boolean done(double[] deficit)
	{
		return deficit[0] < 1 && deficit[1] < 1 && deficit[2] < 1;
	}

	/** Returns each colour's expected useful resin per second, over every order set, under the strategy. */
	private static double[] rates(RecommendationStrategy strategy, int[] resin, int[] target, int[] deficit,
			Pace pace)
	{
		RecommendationPolicy policy = strategy.createPolicy();
		double[] weight = ExpectedValuePolicy.weights(deficit);
		double longRunRate = strategy == RecommendationStrategy.EXPECTED_VALUE
				? ExpectedValuePolicy.longRunRate(deficit, weight)
				: 0;
		double[] gained = new double[3];
		double seconds = 0;
		for (var draw : ExpectedValuePolicy.orderDraws())
		{
			int[] delivery = strategy == RecommendationStrategy.EXPECTED_VALUE
					? ExpectedValuePolicy.bestSubset(OrderSet.of(draw.orders), UNIT_COST, deficit, weight,
							longRunRate)
					: slots(policy.decide(draw.orders, resin, target));
			int bonusFifths = 4 + delivery.length;
			for (int colour = 0; colour < 3; colour++)
			{
				int base = 0;
				for (int slot : delivery)
					base += draw.orders[slot].resinYield(colour);

				gained[colour] += draw.chance * Math.min(deficit[colour], base * bonusFifths / 5);
			}

			seconds += draw.chance * (delivery.length * pace.secondsPerPotion + pace.secondsPerDelivery);
		}

		for (int colour = 0; colour < 3; colour++)
			gained[colour] /= seconds;

		return gained;
	}

	private static int[] slots(Set<Integer> picked)
	{
		return picked.stream()
				.mapToInt(Integer::intValue)
				.sorted()
				.toArray();
	}
}

package com.oveduumnakal.anothermixology;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;

import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/** A one-pixel line across the panel, between sections. */
class SeparatorComponent implements LayoutableRenderableEntity
{
	/** Half as strong as the Potion Orders panel's divider, so it reads as very faint. */
	static final Color COLOR = new Color(255, 255, 255, 45);
	private static final int HEIGHT = 5;

	private Point preferredLocation = new Point();
	private Dimension preferredSize = new Dimension(0, HEIGHT);
	private final Rectangle bounds = new Rectangle();

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int x = preferredLocation.x;
		int y = preferredLocation.y + HEIGHT / 2;
		graphics.setColor(COLOR);
		graphics.drawLine(x, y, x + preferredSize.width - 1, y);
		bounds.setBounds(preferredLocation.x, preferredLocation.y, preferredSize.width, HEIGHT);
		return new Dimension(preferredSize.width, HEIGHT);
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point preferredLocation)
	{
		this.preferredLocation = preferredLocation;
	}

	@Override
	public void setPreferredSize(Dimension preferredSize)
	{
		this.preferredSize = preferredSize;
	}
}

package com.oveduumnakal.anothermixology;

import java.util.List;
import java.util.Set;

import net.runelite.client.util.Text;

/**
 * Decides which clicks on the Alembic, Agitator and Retort are consumed: stations that have nothing to do, and
 * Concentrate clicks that would load the next potion.
 */
final class StationGuard
{
	/**
	 * Maximum value of {@code VarbitID.MM_RETORT_PROGRESS}, a fixed game constant: the bar runs from 0 to 16, then
	 * resets to 0 on completion.
	 */
	static final int RETORT_PROGRESS_MAX = 16;

	private StationGuard()
	{
	}

	static AlchemyObject stationFromTarget(String rawTarget)
	{
		if (rawTarget == null)
			return null;

		String target = Text.removeTags(rawTarget);
		if (target.equals("Alembic"))
			return AlchemyObject.ALEMBIC;

		if (target.equals("Agitator"))
			return AlchemyObject.AGITATOR;

		if (target.equals("Retort"))
			return AlchemyObject.RETORT;

		return null;
	}

	static boolean isStationNeeded(AlchemyObject station, boolean occupied, List<PotionOrder> orders,
			Set<Integer> heldItemIds)
	{
		if (occupied)
			return true;

		for (PotionOrder order : orders)
		{
			if (!order.fulfilled()
					&& order.potionModifier().alchemyObject() == station
					&& heldItemIds.contains(order.potionType().itemId()))
				return true;
		}

		return false;
	}

	/**
	 * Whether a click on a running Agitator or Alembic is consumed: the lock is on, the station is processing a
	 * potion, and its quick action is not up or its quick-action clicks are used up.
	 */
	static boolean runningLockBlocks(boolean lockEnabled, boolean running, boolean quickActionUp)
	{
		return lockEnabled && running && !quickActionUp;
	}

	/**
	 * Whether passive fill alone completes the potion on the next tick. A click then finishes no sooner, so it can
	 * be blocked. Earlier clicks still save at least one tick, whatever the per-click progress.
	 */
	static boolean concentrateCapReached(int currentProgress, int maxProgress)
	{
		return currentProgress >= maxProgress - 1;
	}

	/**
	 * Whether the Retort is running and a Concentrate click still finishes it sooner: from the first progress up to,
	 * but not including, the last tick.
	 */
	static boolean concentrateWorthClicking(int currentProgress, int maxProgress)
	{
		return currentProgress > 0 && !concentrateCapReached(currentProgress, maxProgress);
	}
}

