package com.oveduumnakal.anothermixology;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/** Tests for {@link PotionComparators} and {@link PotionModifier#from(int)}. */
public class PotionComparatorsTest
{
	private static final PotionOrder RETORT = new PotionOrder(0, PotionType.MIXALOT, PotionModifier.CONCENTRATED);
	private static final PotionOrder AGITATOR = new PotionOrder(1, PotionType.MIXALOT, PotionModifier.HOMOGENOUS);
	private static final PotionOrder ALEMBIC = new PotionOrder(2, PotionType.MIXALOT, PotionModifier.CRYSTALISED);

	@Test
	public void byStationSortsAlembicAgitatorRetort()
	{
		assertEquals(List.of(ALEMBIC, AGITATOR, RETORT), sorted(PotionComparators.byStation()));
	}

	@Test
	public void shortestPathSortsAlembicRetortAgitator()
	{
		assertEquals(List.of(ALEMBIC, RETORT, AGITATOR), sorted(PotionComparators.shortestPath()));
	}

	@Test
	public void byStationBreaksTiesByPotionName()
	{
		PotionOrder azure = new PotionOrder(0, PotionType.AZURE_AURA_MIX, PotionModifier.CRYSTALISED);
		PotionOrder alco = new PotionOrder(1, PotionType.ALCO_AUGMENTATOR, PotionModifier.CRYSTALISED);
		List<PotionOrder> orders = new ArrayList<>(List.of(azure, alco));

		orders.sort(PotionComparators.byStation());

		assertEquals(List.of(alco, azure), orders);
	}

	@Test
	public void modifierFromRejectsOutOfRangeValues()
	{
		assertNull(PotionModifier.from(-1));
		assertNull(PotionModifier.from(PotionModifier.values().length));
		assertEquals(PotionModifier.HOMOGENOUS, PotionModifier.from(0));
	}

	private static List<PotionOrder> sorted(Comparator<PotionOrder> comparator)
	{
		List<PotionOrder> orders = new ArrayList<>(List.of(RETORT, AGITATOR, ALEMBIC));
		orders.sort(comparator);
		return orders;
	}
}

package com.oveduumnakal.anothermixology;

import java.util.Arrays;
import java.util.List;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Tests for {@link PotionOrder}. */
public class PotionOrderTest
{
	@Test
	public void rebuiltOrderKeepsItsDoneFlag()
	{
		PotionOrder old = new PotionOrder(1, PotionType.MIXALOT, PotionModifier.CONCENTRATED);
		old.setFulfilled(true);
		PotionOrder rebuilt = new PotionOrder(1, PotionType.MIXALOT, PotionModifier.CONCENTRATED);

		PotionOrder.keepFulfilled(List.of(old), List.of(rebuilt));

		assertTrue(rebuilt.fulfilled());
	}

	@Test
	public void rebuiltOrderKeepsItsDigweedImprovement()
	{
		PotionOrder old = new PotionOrder(1, PotionType.MIXALOT, PotionModifier.CONCENTRATED);
		old.setImproved(true);
		PotionOrder rebuilt = new PotionOrder(1, PotionType.MIXALOT, PotionModifier.CONCENTRATED);

		PotionOrder.keepFulfilled(List.of(old), List.of(rebuilt));

		assertTrue(rebuilt.improved());
	}

	/** A different slot, potion or modifier is a different order, so it starts not done. */
	@Test
	public void changedOrderStartsNotDone()
	{
		PotionOrder old = new PotionOrder(1, PotionType.MIXALOT, PotionModifier.CONCENTRATED);
		old.setFulfilled(true);
		PotionOrder otherSlot = new PotionOrder(2, PotionType.MIXALOT, PotionModifier.CONCENTRATED);
		PotionOrder otherPotion = new PotionOrder(1, PotionType.AZURE_AURA_MIX, PotionModifier.CONCENTRATED);
		PotionOrder otherModifier = new PotionOrder(1, PotionType.MIXALOT, PotionModifier.HOMOGENOUS);

		PotionOrder.keepFulfilled(List.of(old), Arrays.asList(otherSlot, otherPotion, otherModifier));

		assertFalse(otherSlot.fulfilled());
		assertFalse(otherPotion.fulfilled());
		assertFalse(otherModifier.fulfilled());
	}

	@Test
	public void notDoneOrderStaysNotDone()
	{
		PotionOrder old = new PotionOrder(0, PotionType.MIXALOT, PotionModifier.CRYSTALISED);
		PotionOrder rebuilt = new PotionOrder(0, PotionType.MIXALOT, PotionModifier.CRYSTALISED);

		PotionOrder.keepFulfilled(List.of(old), List.of(rebuilt));

		assertFalse(rebuilt.fulfilled());
	}
}

package com.oveduumnakal.anothermixology;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/** Tests for {@link PotionType}. */
public class PotionTypeTest
{
	/** The joined name parts must match the game's order text exactly, or the order names are not recoloured. */
	@Test
	public void namePartsJoinToTheInGameNames()
	{
		assertEquals("Mammoth-might mix", name(PotionType.MAMMOTH_MIGHT_MIX));
		assertEquals("Mystic mana amalgam", name(PotionType.MYSTIC_MANA_AMALGAM));
		assertEquals("Marley's moonlight", name(PotionType.MARLEYS_MOONLIGHT));
		assertEquals("Alco-augmentator", name(PotionType.ALCO_AUGMENTATOR));
		assertEquals("Azure aura mix", name(PotionType.AZURE_AURA_MIX));
		assertEquals("Aqualux amalgam", name(PotionType.AQUALUX_AMALGAM));
		assertEquals("Liplack liquor", name(PotionType.LIPLACK_LIQUOR));
		assertEquals("Megalite liquid", name(PotionType.MEGALITE_LIQUID));
		assertEquals("Anti-leech lotion", name(PotionType.ANTI_LEECH_LOTION));
		assertEquals("Mixalot", name(PotionType.MIXALOT));
	}

	/**
	 * Each name part starts, after any hyphen, with the letter of the component it stands for. Mixalot is the one
	 * exception: its parts are "Mix", "al" and "ot".
	 */
	@Test
	public void eachNamePartStartsWithItsComponentLetter()
	{
		for (PotionType type : PotionType.values())
		{
			if (type == PotionType.MIXALOT)
				continue;

			String[] parts = type.nameParts();
			PotionComponent[] components = type.components();
			for (int i = 0; i < parts.length; i++)
			{
				char first = Character.toUpperCase(parts[i].replace("-", "").charAt(0));
				assertEquals(type + " part " + i, components[i].character(), first);
			}
		}
	}

	@Test
	public void fromIdxRejectsOutOfRangeValues()
	{
		assertNull(PotionType.fromIdx(-1));
		assertNull(PotionType.fromIdx(PotionType.TYPES.length));
		assertEquals(PotionType.MAMMOTH_MIGHT_MIX, PotionType.fromIdx(0));
	}

	@Test
	public void fromItemIdFindsBothTheUnfinishedAndTheFinishedPotion()
	{
		for (PotionType type : PotionType.values())
		{
			assertEquals(type, PotionType.fromItemId(type.itemId()));
			assertEquals(type, PotionType.fromItemId(type.modifiedItemId()));
		}

		assertNull(PotionType.fromItemId(-1));
	}

	@Test
	public void abbreviationIsTheRecipeLetters()
	{
		assertEquals("MAL", PotionType.MIXALOT.abbreviation());
		assertEquals("ALA", PotionType.AQUALUX_AMALGAM.abbreviation());
	}

	@Test
	public void recipeBlocksUseTheIconOfEachComponent()
	{
		assertEquals("<img=10><img=11><img=12>", PotionType.MIXALOT.recipeBlocks(new int[]{10, 11, 12}));
	}

	private static String name(PotionType type)
	{
		return String.join("", type.nameParts());
	}
}

package com.oveduumnakal.anothermixology;

import java.util.Set;

import org.junit.Test;

import static com.oveduumnakal.anothermixology.PotionType.ALCO_AUGMENTATOR;
import static com.oveduumnakal.anothermixology.PotionType.AZURE_AURA_MIX;
import static com.oveduumnakal.anothermixology.PotionType.LIPLACK_LIQUOR;
import static com.oveduumnakal.anothermixology.PotionType.MAMMOTH_MIGHT_MIX;
import static com.oveduumnakal.anothermixology.PotionType.MARLEYS_MOONLIGHT;
import static com.oveduumnakal.anothermixology.PotionType.MEGALITE_LIQUID;
import static com.oveduumnakal.anothermixology.PotionType.MIXALOT;
import static com.oveduumnakal.anothermixology.PotionType.MYSTIC_MANA_AMALGAM;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Tests for the recommendation strategies and the potion data they read. */
public class RecommendationPolicyTest
{
	private static final int[] NO_RESIN = {0, 0, 0};

	@Test
	public void resinYieldFollowsTheRecipeShape()
	{
		assertArrayEquals(new int[]{20, 0, 0}, yields(MAMMOTH_MIGHT_MIX));
		assertArrayEquals(new int[]{20, 10, 0}, yields(MYSTIC_MANA_AMALGAM));
		assertArrayEquals(new int[]{10, 0, 20}, yields(MEGALITE_LIQUID));
		assertArrayEquals(new int[]{20, 20, 20}, yields(MIXALOT));
	}

	@Test
	public void colourCountIsTheNumberOfDifferentPastes()
	{
		assertEquals(1, MAMMOTH_MIGHT_MIX.colourCount());
		assertEquals(2, MYSTIC_MANA_AMALGAM.colourCount());
		assertEquals(3, MIXALOT.colourCount());
	}

	@Test
	public void orderWeightsMatchTheWiki()
	{
		assertEquals(5, LIPLACK_LIQUOR.orderWeight());
		assertEquals(4, MEGALITE_LIQUID.orderWeight());
		assertEquals(3, MIXALOT.orderWeight());
		int total = 0;
		for (PotionType type : PotionType.TYPES)
			total += type.orderWeight();

		assertEquals(42, total);
	}

	@Test
	public void greedyAlwaysBrewsAllThree()
	{
		var policy = RecommendationStrategy.GREEDY.createPolicy();
		var orders = new PotionType[]{MAMMOTH_MIGHT_MIX, ALCO_AUGMENTATOR, LIPLACK_LIQUOR};
		assertEquals(Set.of(0, 1, 2), policy.decide(orders, NO_RESIN, new int[]{0, 0, 100}));
	}

	@Test
	public void bottleneckBrewsAllThreeWhenTwoOrdersGiveTheTopColour()
	{
		var orders = new PotionType[]{LIPLACK_LIQUOR, MEGALITE_LIQUID, MAMMOTH_MIGHT_MIX};
		assertEquals(Set.of(0, 1, 2), new BottleneckPolicy().decide(orders, NO_RESIN, new int[]{100, 100, 1000}));
	}

	@Test
	public void bottleneckBrewsOnlyTheOrderGivingTheTopColour()
	{
		var orders = new PotionType[]{MAMMOTH_MIGHT_MIX, LIPLACK_LIQUOR, ALCO_AUGMENTATOR};
		assertEquals(Set.of(1), new BottleneckPolicy().decide(orders, NO_RESIN, new int[]{100, 100, 1000}));
	}

	@Test
	public void expectedValueBrewsThreeMixalots()
	{
		var orders = new PotionType[]{MIXALOT, MIXALOT, MIXALOT};
		var target = new int[]{5000, 5000, 5000};
		assertEquals(Set.of(0, 1, 2), new ExpectedValuePolicy().decide(orders, NO_RESIN, target));
	}

	@Test
	public void expectedValueBrewsUsefulOrdersRatherThanPayingForAnotherDelivery()
	{
		var orders = new PotionType[]{MARLEYS_MOONLIGHT, AZURE_AURA_MIX, LIPLACK_LIQUOR};
		var resin = new int[]{9882, 8536, 11200};
		var target = new int[]{13800, 11200, 15100};
		assertEquals(Set.of(0, 1, 2), new ExpectedValuePolicy().decide(orders, resin, target));
	}

	@Test
	public void expectedValueSkipsOrdersThatGiveNothingNeeded()
	{
		var orders = new PotionType[]{MAMMOTH_MIGHT_MIX, LIPLACK_LIQUOR, ALCO_AUGMENTATOR};
		var resin = new int[]{1000, 1000, 0};
		var target = new int[]{1000, 1000, 1000};
		assertEquals(Set.of(1), new ExpectedValuePolicy().decide(orders, resin, target));
	}

	@Test
	public void expectedValueIgnoresUnknownSlots()
	{
		var orders = new PotionType[]{null, LIPLACK_LIQUOR, null};
		assertEquals(Set.of(1), new ExpectedValuePolicy().decide(orders, NO_RESIN, new int[]{1000, 1000, 1000}));
	}

	@Test
	public void expectedValueBrewsAllThreeOnceTheTargetIsMet()
	{
		var orders = new PotionType[]{MAMMOTH_MIGHT_MIX, LIPLACK_LIQUOR, ALCO_AUGMENTATOR};
		var resin = new int[]{1000, 1000, 1000};
		assertEquals(Set.of(0, 1, 2), new ExpectedValuePolicy().decide(orders, resin, resin));
	}

	@Test
	public void gainAppliesTheBatchBonusAndCapsEachColour()
	{
		var orders = new PotionType[]{MIXALOT, MIXALOT, MIXALOT};
		var weight = new double[]{1, 1, 1};
		assertEquals(60.0, ExpectedValuePolicy.gain(orders, new int[]{0}, new int[]{999, 999, 999}, weight), 1e-9);
		assertEquals(252.0, ExpectedValuePolicy.gain(orders, new int[]{0, 1, 2}, new int[]{999, 999, 999}, weight),
				1e-9);
		assertEquals(184.0, ExpectedValuePolicy.gain(orders, new int[]{0, 1, 2}, new int[]{999, 999, 16}, weight),
				1e-9);
	}

	@Test
	public void heldDigweedMakesAnOrderWorthBrewing()
	{
		var orders = new PotionType[]{MAMMOTH_MIGHT_MIX, ALCO_AUGMENTATOR, AZURE_AURA_MIX};
		var resin = new int[]{10104, 8742, 11502};
		var target = new int[]{13800, 11200, 15100};
		var withDigweed = new OrderSet(orders, new PotionModifier[3], new boolean[3], 1);
		assertEquals(Set.of(0), new ExpectedValuePolicy().decide(orders, resin, target));
		assertEquals(Set.of(0, 2), new ExpectedValuePolicy().decide(withDigweed, resin, target));
	}

	@Test
	public void digweedGoesOnThePotionWhereDoublingAddsTheMost()
	{
		var orders = OrderSet.of(new PotionType[]{MAMMOTH_MIGHT_MIX, MIXALOT, LIPLACK_LIQUOR});
		assertEquals(1, ExpectedValuePolicy.digweedSlot(orders, Set.of(0, 1), new int[]{1000, 1000, 1000}));
	}

	@Test
	public void digweedSkipsColoursAlreadyAtTarget()
	{
		var orders = OrderSet.of(new PotionType[]{MAMMOTH_MIGHT_MIX, LIPLACK_LIQUOR, MIXALOT});
		assertEquals(1, ExpectedValuePolicy.digweedSlot(orders, Set.of(0, 1), new int[]{0, 1000, 1000}));
	}

	@Test
	public void digweedSkipsImprovedPotions()
	{
		var types = new PotionType[]{MAMMOTH_MIGHT_MIX, MIXALOT, LIPLACK_LIQUOR};
		var improved = new OrderSet(types, new PotionModifier[3], new boolean[]{false, true, false}, 1);
		assertEquals(0, ExpectedValuePolicy.digweedSlot(improved, Set.of(0, 1), new int[]{1000, 1000, 1000}));
		assertEquals(-1, ExpectedValuePolicy.digweedSlot(improved, Set.of(1), new int[]{1000, 1000, 1000}));
	}

	@Test
	public void weightsAreTheCubedRelativeDeficit()
	{
		assertArrayEquals(new double[]{1, 0.125, 0}, ExpectedValuePolicy.weights(new int[]{1000, 500, 0}), 1e-9);
	}

	@Test
	public void retortPotionsCostMoreTimeThanTheOtherStations()
	{
		assertEquals(1, ExpectedValuePolicy.potionCost(null), 1e-9);
		assertTrue(ExpectedValuePolicy.potionCost(PotionModifier.CONCENTRATED)
				> ExpectedValuePolicy.potionCost(PotionModifier.CRYSTALISED));
		assertTrue(ExpectedValuePolicy.potionCost(PotionModifier.CONCENTRATED)
				> ExpectedValuePolicy.potionCost(PotionModifier.HOMOGENOUS));
	}

	@Test
	public void longRunRateIsWithinTheBestPossiblePerPotionYield()
	{
		int[] deficit = {1000, 1000, 1000};
		double rate = ExpectedValuePolicy.longRunRate(deficit, ExpectedValuePolicy.weights(deficit));
		assertTrue(rate > 20 && rate <= 84);
	}

	private static int[] yields(PotionType type)
	{
		return new int[]{type.resinYield(0), type.resinYield(1), type.resinYield(2)};
	}
}

package com.oveduumnakal.anothermixology;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Tests for {@link RetortProgressTracker}. */
public class RetortProgressTrackerTest
{
	@Test
	public void ignoresProgressWhenNoPotionLoaded()
	{
		RetortProgressTracker tracker = new RetortProgressTracker();
		tracker.onProgressChanged(5);
		assertEquals(0, tracker.currentProgress());
		assertFalse(tracker.potionLoaded());
	}

	@Test
	public void tracksCurrentProgressWhilePotionLoaded()
	{
		RetortProgressTracker tracker = new RetortProgressTracker();
		tracker.onPotionLoaded();
		tracker.onProgressChanged(2);
		tracker.onProgressChanged(4);
		assertTrue(tracker.potionLoaded());
		assertEquals(4, tracker.currentProgress());
	}

	/** A cleared potion resets the progress, so the next potion starts from 0. */
	@Test
	public void progressResetsAcrossPotions()
	{
		RetortProgressTracker tracker = new RetortProgressTracker();
		tracker.onPotionLoaded();
		tracker.onProgressChanged(15);
		tracker.onPotionCleared();
		assertEquals(0, tracker.currentProgress());
		tracker.onPotionLoaded();
		assertEquals(0, tracker.currentProgress());
	}
}

package com.oveduumnakal.anothermixology;

import java.util.List;

import org.junit.Test;

import static com.oveduumnakal.anothermixology.RewardItem.ALDARIUM;
import static com.oveduumnakal.anothermixology.RewardItem.POTION_STORAGE;
import static com.oveduumnakal.anothermixology.RewardItem.REAGENT_POUCH;
import static org.junit.Assert.assertEquals;

/** Tests for {@link RewardPriority}. */
public class RewardPriorityTest
{
	@Test
	public void savesAndReadsTheOrder()
	{
		var order = List.of(POTION_STORAGE, REAGENT_POUCH);
		assertEquals(order, RewardPriority.parse(RewardPriority.format(order)));
	}

	@Test
	public void readingSkipsUnknownNamesAndRepeats()
	{
		assertEquals(List.of(POTION_STORAGE, REAGENT_POUCH),
				RewardPriority.parse("POTION_STORAGE, GONE,REAGENT_POUCH,POTION_STORAGE"));
		assertEquals(List.of(), RewardPriority.parse(""));
	}

	@Test
	public void aNewlyTickedRewardGoesToTheBottom()
	{
		var order = RewardPriority.reconcile(List.of(POTION_STORAGE), List.of(REAGENT_POUCH, POTION_STORAGE));
		assertEquals(List.of(POTION_STORAGE, REAGENT_POUCH), order);
	}

	@Test
	public void anUntickedRewardLeavesTheOrder()
	{
		var order = RewardPriority.reconcile(List.of(POTION_STORAGE, ALDARIUM, REAGENT_POUCH),
				List.of(REAGENT_POUCH, POTION_STORAGE));
		assertEquals(List.of(POTION_STORAGE, REAGENT_POUCH), order);
	}

	@Test
	public void sortsSelectionsIntoTheOrder()
	{
		var pouch = new Goal.Selection(REAGENT_POUCH, 1);
		var storage = new Goal.Selection(POTION_STORAGE, 1);
		var aldarium = new Goal.Selection(ALDARIUM, 20);

		var sorted = RewardPriority.sort(List.of(pouch, storage, aldarium), List.of(POTION_STORAGE, REAGENT_POUCH));
		assertEquals(List.of(storage, pouch, aldarium), sorted);
	}

	@Test
	public void movesARewardOnePlaceAndStopsAtTheEnds()
	{
		var order = List.of(REAGENT_POUCH, POTION_STORAGE, ALDARIUM);
		assertEquals(List.of(POTION_STORAGE, REAGENT_POUCH, ALDARIUM),
				RewardPriority.move(order, POTION_STORAGE, -1));
		assertEquals(List.of(REAGENT_POUCH, ALDARIUM, POTION_STORAGE),
				RewardPriority.move(order, POTION_STORAGE, 1));
		assertEquals(order, RewardPriority.move(order, REAGENT_POUCH, -1));
		assertEquals(order, RewardPriority.move(order, ALDARIUM, 1));
	}
}

