	{
		int[] resin = {13800, 11200, 15100};
		var rows = RewardRows.build(POUCH_AND_GOGGLES, resin, RewardOrder.EACH_ON_ITS_OWN);

		assertEquals(3, rows.size());
		assertTrue(rows.get(0).ready());
		assertArrayEquals(new int[]{13800, 11200, 15100}, rows.get(0).target);
		assertEquals("All Rewards:", rows.get(2).label);
		assertFalse(rows.get(2).ready());
	}

	@Test
	public void inOrderCountsOnlyTheResinLeftAfterTheRowsAbove()
	{
		int[] resin = {13800, 11200, 15100};
		var rows = RewardRows.build(POUCH_AND_GOGGLES, resin, RewardOrder.IN_ORDER);

		assertTrue(rows.get(0).ready());
		assertEquals(0, rows.get(1).progress, 1e-9);
		int[] allTarget = rows.get(2).target;
		int[] gogglesTarget = rows.get(1).target;
		assertArrayEquals(allTarget, gogglesTarget);
	}

	@Test
	public void progressIsTheShareOfTheCostCovered()
	{
		assertEquals(0.5, RewardRows.progress(new int[]{100, 0, 50}, new int[]{100, 0, 200}), 1e-9);
		assertEquals(1, RewardRows.progress(new int[]{0, 0, 0}, new int[]{0, 0, 0}), 1e-9);
	}

	@Test
	public void quantityGoesInTheLabel()
	{
		var rows = RewardRows.build(List.of(new Goal.Selection(RewardItem.ALDARIUM, 20)), new int[3],
				RewardOrder.EACH_ON_ITS_OWN);
		assertEquals(RewardItem.ALDARIUM.itemName() + " x20", rows.get(0).label);
	}

	@Test
	public void formatsTimeAsHoursMinutesSeconds()
	{
		assertEquals("08h 53m 09s", RewardRows.formatTime(8 * 3600 + 53 * 60 + 9));
		assertEquals("00h 00m 00s", RewardRows.formatTime(0));
	}

	@Test
	public void estimatesCountDownAndStopAtZero()
	{
		var estimates = new RewardEstimates(List.of(), new double[]{100}, 1_000);
		assertEquals(70, estimates.secondsLeft(0, 31_000));
		assertEquals(0, estimates.secondsLeft(0, 500_000));
	}

	@Test
	public void rowsTickOnTheSameSecond()
	{
		var estimates = new RewardEstimates(List.of(), new double[]{100.2, 50.7}, 0);
		for (long played = 0; played < 5_000; played += 100)
		{
			long first = estimates.secondsLeft(0, played);
			long second = estimates.secondsLeft(1, played);
			assertEquals(100 - 51, first - second);
		}
	}
}

package com.oveduumnakal.anothermixology;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Tests for {@link RewardTimeEstimator} against the variant simulator's averages (2,000 Reagent Pouch runs each, the
 * Expected value strategy, {@link Pace#DEFAULT} timings), which it must match within 5 %.
 */
public class RewardTimeEstimatorTest
{
	private static final int[] REAGENT_POUCH = {13800, 11200, 15100};

	private static void assertWithin5Percent(double expectedHours, int[] resin)
	{
		double hours = RewardTimeEstimator.seconds(RecommendationStrategy.EXPECTED_VALUE, resin, REAGENT_POUCH,
				Pace.DEFAULT) / 3600;
		assertEquals(expectedHours, hours, expectedHours * 0.05);
	}

	@Test
	public void matchesTheSimulatorFromNothing()
	{
		assertWithin5Percent(5.790, new int[]{0, 0, 0});
	}

	@Test
	public void matchesTheSimulatorHalfWay()
	{
		assertWithin5Percent(2.909, new int[]{6900, 5600, 7550});
	}

	@Test
	public void matchesTheSimulatorNearTheEnd()
	{
		assertWithin5Percent(1.451, new int[]{10104, 8742, 11502});
		assertWithin5Percent(0.296, new int[]{13000, 10800, 14500});
	}

	@Test
	public void reachedTargetTakesNoTime()
	{
		assertEquals(0, RewardTimeEstimator.seconds(RecommendationStrategy.EXPECTED_VALUE, REAGENT_POUCH,
				REAGENT_POUCH, Pace.DEFAULT), 1e-9);
	}

	@Test
	public void otherStrategiesGiveAnEstimateToo()
	{
		double greedy = RewardTimeEstimator.seconds(RecommendationStrategy.GREEDY, new int[3], REAGENT_POUCH,
				Pace.DEFAULT);
		assertTrue(greedy > 4 * 3600 && greedy < 9 * 3600);
	}
}

package com.oveduumnakal.anothermixology;

import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;

import com.google.inject.Guice;
import com.google.inject.testing.fieldbinder.Bind;
import com.google.inject.testing.fieldbinder.BoundFieldModule;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import net.runelite.api.Client;
import net.runelite.api.GraphicsObject;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.GraphicsObjectCreated;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.overlay.OverlayManager;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Tests the Agitator and Alembic running locks through the plugin, with a mocked client: clicks on a running station
 * are consumed except during its quick-action window, which opens on the spot animation and closes on the progress
 * updates that follow. A station counts as running only while the player's last click went to it.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class RunningStationLockTest
{
	@Mock
	@Bind
	private Client client;

	@Mock
	@Bind
	private AnotherMixologyConfig config;

	@Mock
	@Bind
	private ConfigManager configManager;

	@Mock
	@Bind
	private OverlayManager overlayManager;

	@Mock
	@Bind
	private Notifier notifier;

	@Mock
	@Bind
	private ClientThread clientThread;

	@Mock
	@Bind
	private ScheduledExecutorService executor;

	@Mock
	@Bind
	private AnotherMixologyOverlay overlay;

	@Mock
	@Bind
	private InventoryPotionOverlay potionOverlay;

	@Mock
	@Bind
	private OrdersPanelOverlay ordersPanelOverlay;

	@Mock
	@Bind
	private GoalInfoBoxOverlay goalInfoBoxOverlay;

	@Inject
	private AnotherMixologyPlugin plugin;

	@Before
	public void setUp()
	{
		Guice.createInjector(BoundFieldModule.of(this)).injectMembers(this);
		when(config.potionOrderSorting()).thenReturn(PotionOrderSorting.VANILLA);
		when(config.lockAgitatorWhileRunning()).thenReturn(true);
		when(config.lockAlembicWhileRunning()).thenReturn(true);
		when(client.getWidget(InterfaceID.MM_OVERLAY, 0)).thenReturn(mock(Widget.class));

		WidgetLoaded loaded = new WidgetLoaded();
		loaded.setGroupId(InterfaceID.MM_OVERLAY);
		plugin.onWidgetLoaded(loaded);
	}

	@Test
	public void idleStationsAreNotLocked()
	{
		assertFalse(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
		assertFalse(click("Alembic", AlchemyObject.ALEMBIC).isConsumed());
	}

	@Test
	public void runningAgitatorIsLockedOutsideTheQuickAction()
	{
		start("Agitator", AlchemyObject.AGITATOR, VarbitID.MM_LAB_AGITATOR_POTION);

		assertTrue(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
	}

	/** Walking away pauses the station with its potion still in it; the next click must resume it. */
	@Test
	public void pausedStationCanBeResumed()
	{
		start("Agitator", AlchemyObject.AGITATOR, VarbitID.MM_LAB_AGITATOR_POTION);
		start("Alembic", AlchemyObject.ALEMBIC, VarbitID.MM_LAB_ALEMBIC_POTION);
		walk();

		assertFalse(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
		assertTrue(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
		assertFalse(click("Alembic", AlchemyObject.ALEMBIC).isConsumed());
	}

	/** Interface clicks, such as minimising the chat box, do not stop a station, so the lock stays. */
	@Test
	public void interfaceClickKeepsTheLock()
	{
		start("Agitator", AlchemyObject.AGITATOR, VarbitID.MM_LAB_AGITATOR_POTION);
		menuClick(MenuAction.CC_OP);

		assertTrue(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
	}

	/** Clicking another object stops the station, like walking away. */
	@Test
	public void objectClickPausesTheStation()
	{
		start("Agitator", AlchemyObject.AGITATOR, VarbitID.MM_LAB_AGITATOR_POTION);
		click("Mixing vessel", AlchemyObject.MIXING_VESSEL);

		assertFalse(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
	}

	/** A blocked click does not count as working the clicked station or as clicking away. */
	@Test
	public void blockedClickKeepsTheLock()
	{
		start("Agitator", AlchemyObject.AGITATOR, VarbitID.MM_LAB_AGITATOR_POTION);
		click("Agitator", AlchemyObject.AGITATOR);

		assertTrue(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
	}

	/** The Agitator's window stays open for two progress updates after the spot animation. */
	@Test
	public void agitatorQuickActionWindowLetsClicksThroughForTwoUpdates()
	{
		start("Agitator", AlchemyObject.AGITATOR, VarbitID.MM_LAB_AGITATOR_POTION);
		spotAnim(SpotanimID.VFX_MACHINERY_ALCHEMY01_AGITATOR01);
		assertFalse(click("Agitator", AlchemyObject.AGITATOR).isConsumed());

		tick(1);
		varbit(VarbitID.MM_AGITATOR_PROGRESS, 5);
		assertFalse(click("Agitator", AlchemyObject.AGITATOR).isConsumed());

		tick(2);
		varbit(VarbitID.MM_AGITATOR_PROGRESS, 6);
		assertTrue(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
	}

	/** The Alembic's window closes on the first progress update after the spot animation. */
	@Test
	public void alembicQuickActionWindowLetsClicksThroughForOneUpdate()
	{
		start("Alembic", AlchemyObject.ALEMBIC, VarbitID.MM_LAB_ALEMBIC_POTION);
		spotAnim(SpotanimID.VFX_MACHINERY_ALCHEMY01_ALEMBIC01);
		assertFalse(click("Alembic", AlchemyObject.ALEMBIC).isConsumed());

		varbit(VarbitID.MM_ALEMBIC_PROGRESS, 5);
		assertTrue(click("Alembic", AlchemyObject.ALEMBIC).isConsumed());
	}

	/** The Alembic's quick action lets one click through; a second click in the same window is consumed. */
	@Test
	public void alembicQuickActionLetsOneClickThrough()
	{
		start("Alembic", AlchemyObject.ALEMBIC, VarbitID.MM_LAB_ALEMBIC_POTION);
		spotAnim(SpotanimID.VFX_MACHINERY_ALCHEMY01_ALEMBIC01);

		assertFalse(click("Alembic", AlchemyObject.ALEMBIC).isConsumed());
		assertTrue(click("Alembic", AlchemyObject.ALEMBIC).isConsumed());
	}

	/** The Agitator's two-tick quick action lets one click through per tick. */
	@Test
	public void agitatorQuickActionLetsOneClickThroughPerTick()
	{
		start("Agitator", AlchemyObject.AGITATOR, VarbitID.MM_LAB_AGITATOR_POTION);
		spotAnim(SpotanimID.VFX_MACHINERY_ALCHEMY01_AGITATOR01);

		assertFalse(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
		assertTrue(click("Agitator", AlchemyObject.AGITATOR).isConsumed());

		tick(1);
		varbit(VarbitID.MM_AGITATOR_PROGRESS, 5);
		assertFalse(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
		assertTrue(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
	}

	/** Each new quick action gives the station its clicks again. */
	@Test
	public void nextQuickActionRestoresTheClicks()
	{
		start("Alembic", AlchemyObject.ALEMBIC, VarbitID.MM_LAB_ALEMBIC_POTION);
		spotAnim(SpotanimID.VFX_MACHINERY_ALCHEMY01_ALEMBIC01);
		click("Alembic", AlchemyObject.ALEMBIC);
		tick(1);
		varbit(VarbitID.MM_ALEMBIC_PROGRESS, 5);

		tick(2);
		spotAnim(SpotanimID.VFX_MACHINERY_ALCHEMY01_ALEMBIC01);
		assertFalse(click("Alembic", AlchemyObject.ALEMBIC).isConsumed());
	}

	@Test
	public void lockOffLetsRunningStationClicksThrough()
	{
		when(config.lockAgitatorWhileRunning()).thenReturn(false);
		start("Agitator", AlchemyObject.AGITATOR, VarbitID.MM_LAB_AGITATOR_POTION);

		assertFalse(click("Agitator", AlchemyObject.AGITATOR).isConsumed());
	}

	/** Clicks an idle station and loads a potion into it, as the game does. */
	private void start(String target, AlchemyObject object, int potionVarbit)
	{
		assertFalse(click(target, object).isConsumed());
		varbit(potionVarbit, 1);
	}

	private void tick(int tickCount)
	{
		when(client.getTickCount()).thenReturn(tickCount);
	}

	private void walk()
	{
		menuClick(MenuAction.WALK);
	}

	private void menuClick(MenuAction action)
	{
		MenuEntry entry = mock(MenuEntry.class);
		when(entry.getType()).thenReturn(action);
		plugin.onMenuOptionClicked(new MenuOptionClicked(entry));
	}

	private void varbit(int varbitId, int value)
	{
		VarbitChanged event = new VarbitChanged();
		event.setVarbitId(varbitId);
		event.setVarpId(-1);
		event.setValue(value);
		plugin.onVarbitChanged(event);
	}

	private void spotAnim(int id)
	{
		GraphicsObject graphicsObject = mock(GraphicsObject.class);
		when(graphicsObject.getId()).thenReturn(id);
		plugin.onGraphicsObjectCreated(new GraphicsObjectCreated(graphicsObject));
	}

	private MenuOptionClicked click(String target, AlchemyObject object)
	{
		MenuEntry entry = mock(MenuEntry.class);
		when(entry.getType()).thenReturn(MenuAction.GAME_OBJECT_FIRST_OPTION);
		when(entry.getIdentifier()).thenReturn(object.objectId());
		when(entry.getTarget()).thenReturn(target);
		MenuOptionClicked event = new MenuOptionClicked(entry);
		plugin.onMenuOptionClicked(event);
		return event;
	}
}

package com.oveduumnakal.anothermixology;

import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Tests for {@link StationGuard}. */
public class StationGuardTest
{
	@Test
	public void stationFromTargetStripsTagsAndMatchesNames()
	{
		assertEquals(AlchemyObject.RETORT, StationGuard.stationFromTarget("<col=00ff00>Retort</col>"));
		assertEquals(AlchemyObject.ALEMBIC, StationGuard.stationFromTarget("Alembic"));
		assertEquals(AlchemyObject.AGITATOR, StationGuard.stationFromTarget("Agitator"));
		assertNull(StationGuard.stationFromTarget("Bank booth"));
		assertNull(StationGuard.stationFromTarget(null));
	}

	@Test
	public void occupiedStationIsAlwaysNeeded()
	{
		assertTrue(StationGuard.isStationNeeded(
				AlchemyObject.RETORT, true, Collections.emptyList(), Collections.emptySet()));
	}

	@Test
	public void emptyStationNeededWhenAnUnfulfilledOrderMatchesAHeldPotion()
	{
		PotionType type = firstConcentrateType();
		PotionOrder order = new PotionOrder(0, type, PotionModifier.CONCENTRATED);
		List<PotionOrder> orders = Collections.singletonList(order);
		Set<Integer> held = new HashSet<>();
		held.add(type.itemId());

		assertTrue(StationGuard.isStationNeeded(AlchemyObject.RETORT, false, orders, held));
	}

	@Test
	public void emptyStationNotNeededWhenOrderFulfilled()
	{
		PotionType type = firstConcentrateType();
		PotionOrder order = new PotionOrder(0, type, PotionModifier.CONCENTRATED);
		order.setFulfilled(true);
		List<PotionOrder> orders = Collections.singletonList(order);
		Set<Integer> held = new HashSet<>();
		held.add(type.itemId());

		assertFalse(StationGuard.isStationNeeded(AlchemyObject.RETORT, false, orders, held));
	}

	@Test
	public void emptyStationNotNeededWhenPotionNotHeld()
	{
		PotionType type = firstConcentrateType();
		PotionOrder order = new PotionOrder(0, type, PotionModifier.CONCENTRATED);
		List<PotionOrder> orders = Collections.singletonList(order);

		assertFalse(StationGuard.isStationNeeded(
				AlchemyObject.RETORT, false, orders, Collections.emptySet()));
	}

	/**
	 * With a maximum of 16, passive fill completes from 15 on the next tick, so the cap blocks at 15. At 14 a click
	 * still finishes one tick sooner, so it is let through.
	 */
	@Test
	public void concentrateCapBlocksOnlyOnTheLastTick()
	{
		assertFalse(StationGuard.concentrateCapReached(13, 16));
		assertFalse(StationGuard.concentrateCapReached(14, 16));
		assertTrue(StationGuard.concentrateCapReached(15, 16));
	}

	/** The quick-action colour shows from the first progress up to the last tick. */
	@Test
	public void concentrateWorthClickingUntilTheLastTick()
	{
		assertFalse(StationGuard.concentrateWorthClicking(0, 16));
		assertTrue(StationGuard.concentrateWorthClicking(1, 16));
		assertTrue(StationGuard.concentrateWorthClicking(14, 16));
		assertFalse(StationGuard.concentrateWorthClicking(15, 16));
	}

	@Test
	public void runningLockBlocksOnlyWhileRunningWithoutQuickAction()
	{
		assertTrue(StationGuard.runningLockBlocks(true, true, false));
		assertFalse(StationGuard.runningLockBlocks(true, true, true));
		assertFalse(StationGuard.runningLockBlocks(true, false, false));
		assertFalse(StationGuard.runningLockBlocks(false, true, false));
	}

	/** Any potion type works, because the modifier (concentrated) drives the station. */
	private static PotionType firstConcentrateType()
	{
		return PotionType.values()[0];
	}
}
